window.CATALOGO_BUSCA = {"versao":"7113e9b85e","modulos":{"m01":{"glossario":[{"termo":"Engenharia de Produção","definicao":"Engenharia que projeta, melhora e implanta sistemas produtivos integrados de pessoas, materiais, informação, equipamentos, energia e dinheiro."},{"termo":"ART","definicao":"Anotação de Responsabilidade Técnica, registrada no Crea para serviços de engenharia."},{"termo":"Subotimização","definicao":"Melhorar uma parte do sistema piorando o resultado do todo."},{"termo":"Administração Científica","definicao":"Abordagem de Taylor: estudo de tempos, padronização e separação entre planejamento e execução."},{"termo":"Produção em massa","definicao":"Alto volume de produtos padronizados, com linhas dedicadas e economia de escala."},{"termo":"Produção enxuta","definicao":"Sistema derivado da Toyota que busca variedade com baixo custo, eliminando desperdícios."},{"termo":"Estudos de Hawthorne","definicao":"Pesquisas (anos 1920–30) que evidenciaram a influência de fatores sociais no desempenho."},{"termo":"ABEPRO","definicao":"Associação Brasileira de Engenharia de Produção; define 10 áreas da profissão."},{"termo":"Sistema de produção","definicao":"Conjunto que transforma entradas em saídas de valor, com realimentação."},{"termo":"Recursos transformados","definicao":"Materiais, informações e clientes que são processados."},{"termo":"Recursos transformadores","definicao":"Instalações e pessoas que realizam a transformação."},{"termo":"SIPOC","definicao":"Fornecedores, entradas, processo, saídas e clientes: visão do processo numa linha."},{"termo":"4 Vs","definicao":"Volume, variedade, variação da demanda e visibilidade."},{"termo":"Linha de frente / retaguarda","definicao":"Atividades com contato com o cliente × atividades de processamento sem o cliente."},{"termo":"Servitização","definicao":"Oferta de serviços ou resultados associados ao produto, em vez de só o produto."},{"termo":"Matriz produto-processo","definicao":"Relação entre volume/variedade do produto e o tipo de processo adequado (Hayes e Wheelwright)."},{"termo":"Customização em massa","definicao":"Oferta de variedade com custos próximos aos da produção em massa."},{"termo":"Objetivos de desempenho","definicao":"Qualidade, rapidez, confiabilidade, flexibilidade e custo."},{"termo":"Ganhador de pedido","definicao":"Critério que faz o cliente escolher a empresa."},{"termo":"Qualificador","definicao":"Critério mínimo para a empresa ser considerada pelo cliente."},{"termo":"Fábrica focada","definicao":"Operação concentrada em poucos objetivos coerentes (Skinner)."},{"termo":"Cone de areia","definicao":"Modelo de construção cumulativa de capacidades: qualidade, confiabilidade, flexibilidade, custo."},{"termo":"Produtividade","definicao":"Saídas ÷ entradas."},{"termo":"Produtividade multifatorial","definicao":"Saídas ÷ soma de vários recursos, em unidades monetárias."},{"termo":"Eficiência","definicao":"Uso dos recursos; produção real ÷ produção padrão."},{"termo":"Eficácia","definicao":"Atingir o objetivo."},{"termo":"Efetividade","definicao":"Gerar impacto duradouro (eficaz e eficiente)."},{"termo":"OTIF","definicao":"Pedidos entregues no prazo e completos ÷ total de pedidos."},{"termo":"Lei de Goodhart","definicao":"Quando uma medida vira meta, tende a deixar de ser uma boa medida."}],"flashcards":[{"id":"m01-f01","frente":"O que faz a Engenharia de Produção?","verso":"Projeta, melhora e implanta sistemas produtivos integrados (pessoas, materiais, informação, equipamentos, energia e dinheiro)."},{"id":"m01-f02","frente":"Mnemônico das 10 áreas da ABEPRO","verso":"\"Onde Logo Pesquisei Qual Produto O Engenheiro Traria Sem Erro\""},{"id":"m01-f03","frente":"10 áreas da ABEPRO","verso":"Operações, Logística, Pesquisa Operacional, Qualidade, Produto, Organizacional, Econômica, Trabalho, Sustentabilidade, Educação."},{"id":"m01-f04","frente":"Engenharia do Trabalho estuda…","verso":"Ergonomia, segurança, higiene e organização do trabalho (NÃO é direito trabalhista)."},{"id":"m01-f05","frente":"Pesquisa Operacional é…","verso":"Uso de modelos matemáticos para apoiar decisões: otimização, simulação, filas."},{"id":"m01-f06","frente":"Taylor (1911)","verso":"Administração Científica: estudo de tempos e padronização do trabalho."},{"id":"m01-f07","frente":"Ford (1913)","verso":"Linha de montagem móvel → produção em massa."},{"id":"m01-f08","frente":"Taiichi Ohno","verso":"Sistema Toyota de Produção → base do Lean."},{"id":"m01-f09","frente":"Modelo de sistema de produção","verso":"Entradas (materiais, informações, clientes) → Transformação (instalações e pessoas) → Saídas (bens e serviços)."},{"id":"m01-f10","frente":"3 diferenças entre bens e serviços","verso":"Serviços são intangíveis, não estocáveis e produzidos/consumidos ao mesmo tempo (alto contato com cliente)."},{"id":"m01-f11","frente":"Tipos de processo (manufatura), menor → maior volume","verso":"Projeto → Jobbing → Lotes → Massa → Contínuo (\"Pra Já Levo Mais Coisa\")."},{"id":"m01-f12","frente":"Tipos de processo em serviços","verso":"Serviços profissionais → Loja de serviços → Serviços de massa."},{"id":"m01-f13","frente":"5 objetivos de desempenho","verso":"Qualidade, Rapidez, Confiabilidade, Flexibilidade, Custo (\"Qual Rato Come Farinha Cara?\")."},{"id":"m01-f14","frente":"Rapidez × Confiabilidade","verso":"Rapidez = entregar logo. Confiabilidade = entregar quando prometeu."},{"id":"m01-f15","frente":"Níveis de decisão","verso":"Estratégico (anos) → Tático (meses) → Operacional (dias/horas)."},{"id":"m01-f16","frente":"Fórmula da produtividade","verso":"Produtividade = Saídas ÷ Entradas."},{"id":"m01-f17","frente":"Variação da produtividade","verso":"(P atual − P anterior) ÷ P anterior × 100."},{"id":"m01-f18","frente":"Eficácia × Eficiência × Efetividade","verso":"Eficaz acerta o alvo, eficiente poupa a flecha, efetivo ganha a guerra."},{"id":"m01-f19","frente":"Primeiro curso de Eng. de Produção no Brasil","verso":"Escola Politécnica da USP, 1958."},{"id":"m01-f21","frente":"Fórmula da eficiência operacional","verso":"Produção real ÷ Produção padrão × 100."},{"id":"m01-f22","frente":"Entradas transformadas × recursos transformadores","verso":"Transformadas: materiais, informações, clientes. Transformadores: instalações e pessoas."},{"id":"m01-f20","frente":"Regra de ouro da melhoria","verso":"Sem número não existe melhoria, só opinião: meça antes e depois."}],"formulas":{"m01-l7":[{"titulo":"Produtividade","texto":"**Produtividade = Saídas ÷ Entradas**","nivel":"facil"},{"titulo":"Variação","texto":"**Variação (%) = (P atual − P anterior) ÷ P anterior × 100**","nivel":"facil"},{"titulo":"Eficiência operacional","texto":"**Eficiência (%) = Produção real ÷ Produção padrão × 100**","nivel":"facil"},{"titulo":"Produtividade multifatorial","texto":"**PMF = valor das saídas ÷ (mão de obra + materiais + energia + capital)**","nivel":"medio"},{"titulo":"Eficiência em relação ao padrão","texto":"**Eficiência = produção real ÷ produção padrão × 100%**","nivel":"medio"}],"m01-l8":[{"titulo":"Indicadores do caso","texto":"OTIF = pedidos no prazo e completos ÷ pedidos entregues","nivel":"medio"}]}},"m13":{"glossario":[{"termo":"População","definicao":"Conjunto completo de itens ou pessoas que se quer estudar."},{"termo":"Amostra","definicao":"Parte da população efetivamente medida; deve ser aleatória e representativa."},{"termo":"Parâmetro","definicao":"Medida da população (μ, σ, p)."},{"termo":"Estatística","definicao":"Medida calculada na amostra (x̄, s, p̂)."},{"termo":"Variável qualitativa","definicao":"Expressa categorias (nominal ou ordinal)."},{"termo":"Variável quantitativa","definicao":"Expressa números (discreta, por contagem; contínua, por medição)."},{"termo":"Histograma","definicao":"Gráfico de barras coladas que mostra a distribuição de uma variável contínua por faixas."},{"termo":"Diagrama de Pareto","definicao":"Barras em ordem decrescente com curva acumulada; separa os poucos vitais dos muitos triviais."},{"termo":"Média","definicao":"Soma dos valores dividida pela quantidade."},{"termo":"Mediana","definicao":"Valor central dos dados ordenados; resistente a outliers."},{"termo":"Moda","definicao":"Valor mais frequente."},{"termo":"Amplitude","definicao":"Maior valor menos o menor."},{"termo":"Variância","definicao":"Média dos quadrados dos desvios em relação à média."},{"termo":"Desvio padrão","definicao":"Raiz da variância; variação típica na unidade dos dados."},{"termo":"Coeficiente de variação","definicao":"Desvio padrão dividido pela média, em %; compara variações de escalas diferentes."},{"termo":"Quartis","definicao":"Valores que dividem os dados ordenados em quatro partes iguais."},{"termo":"Boxplot","definicao":"Gráfico com mediana, quartis e outliers."},{"termo":"Outlier","definicao":"Valor muito distante dos demais; investigar antes de descartar."},{"termo":"Probabilidade","definicao":"Medida, de 0 a 1, da chance de um evento ocorrer."},{"termo":"Eventos independentes","definicao":"Um não altera a probabilidade do outro; P(A e B) = P(A)·P(B)."},{"termo":"Distribuição binomial","definicao":"Número de sucessos em n tentativas independentes com a mesma probabilidade p."},{"termo":"Distribuição de Poisson","definicao":"Número de ocorrências em um intervalo, com taxa média λ."},{"termo":"Distribuição normal","definicao":"Curva em forma de sino, simétrica, definida por μ e σ."},{"termo":"Escore Z","definicao":"Quantos desvios padrão um valor está da média: Z = (x − μ)/σ."},{"termo":"Teorema Central do Limite","definicao":"Médias de amostras tendem à normal, com desvio padrão σ/√n."},{"termo":"Erro padrão","definicao":"Desvio padrão da média amostral: σ/√n."},{"termo":"Intervalo de confiança","definicao":"Faixa que, com certa confiança, contém o parâmetro da população."},{"termo":"Teste de hipóteses","definicao":"Procedimento para decidir, com dados, entre H0 e H1 controlando o risco de erro."},{"termo":"Valor-p","definicao":"Probabilidade de observar um resultado tão extremo se H0 for verdadeira."},{"termo":"Correlação (r)","definicao":"Força e sentido da relação linear entre duas variáveis, de −1 a 1."},{"termo":"Regressão linear","definicao":"Reta que estima uma variável a partir de outra: y = a + b·x."},{"termo":"Cp e Cpk","definicao":"Índices de capacidade: Cp compara a tolerância com a variação; Cpk considera também a centralização."}],"flashcards":[{"id":"m13-f01","frente":"População × Amostra","verso":"População = o conjunto inteiro. Amostra = a parte que você mede (aleatória e representativa)."},{"id":"m13-f02","frente":"Parâmetro × Estatística","verso":"Parâmetro descreve a população (μ, σ). Estatística é calculada na amostra (x̄, s)."},{"id":"m13-f03","frente":"Tipos de variável (NO-OR / DI-CO)","verso":"Qualitativa nominal e ordinal; quantitativa discreta (conta) e contínua (mede)."},{"id":"m13-f04","frente":"Histograma × gráfico de barras","verso":"Histograma: barras coladas, eixo contínuo (faixas). Barras: categorias separadas."},{"id":"m13-f05","frente":"Média, mediana e moda","verso":"Média = soma ÷ n. Mediana = valor do meio (ordenado). Moda = o que mais aparece."},{"id":"m13-f06","frente":"Quando usar a mediana?","verso":"Com outliers ou dados assimétricos (salários, lead time, atendimento)."},{"id":"m13-f07","frente":"Média > mediana indica…","verso":"Assimetria positiva (cauda à direita)."},{"id":"m13-f08","frente":"IQR e regra do outlier","verso":"IQR = Q3 − Q1. Outlier: < Q1 − 1,5·IQR ou > Q3 + 1,5·IQR."},{"id":"m13-f09","frente":"Os 5 números do boxplot","verso":"Mínimo, Q1, mediana, Q3, máximo (+ outliers como pontos)."},{"id":"m13-f10","frente":"Variância e desvio-padrão amostral","verso":"s² = Σ(x − x̄)² ÷ (n − 1); s = √s². \"A amostra é humilde: divide por um a menos.\""},{"id":"m13-f11","frente":"Coeficiente de variação","verso":"CV = s ÷ x̄ × 100%. Compara variações com médias/unidades diferentes."},{"id":"m13-f12","frente":"Regras do OU e do E","verso":"OU soma: P(A)+P(B)−P(A e B). E multiplica (independentes): P(A)×P(B)."},{"id":"m13-f13","frente":"\"Pelo menos um\"","verso":"P(pelo menos 1) = 1 − P(nenhum)."},{"id":"m13-f14","frente":"Binomial × Poisson","verso":"Binomial: nº de sucessos em n tentativas (defeituosas). Poisson: nº de eventos por tempo (chegadas)."},{"id":"m13-f15","frente":"Regra empírica da Normal","verso":"68% em ±1σ; 95% em ±2σ; 99,7% em ±3σ."},{"id":"m13-f16","frente":"Escore Z","verso":"Z = (x − μ) ÷ σ: quantos desvios o valor está da média."},{"id":"m13-f17","frente":"Z de cor (90%, 95%, 99%)","verso":"1,645 · 1,96 · 2,58."},{"id":"m13-f18","frente":"Cauda acima de Z = 2 e Z = 3","verso":"Z = 2 → 2,28%. Z = 3 → 0,135%."},{"id":"m13-f19","frente":"Teorema Central do Limite","verso":"Médias de amostras (n ≥ 30) seguem ~normal com média μ e desvio σ ÷ √n."},{"id":"m13-f20","frente":"Erro padrão","verso":"EP = σ ÷ √n. Metade do erro exige 4× mais amostra."},{"id":"m13-f21","frente":"Intervalo de confiança da média","verso":"x̄ ± z · s ÷ √n. Fala da MÉDIA, não das peças individuais."},{"id":"m13-f22","frente":"Tamanho de amostra","verso":"n = (z · σ ÷ E)², arredondando para cima."},{"id":"m13-f23","frente":"Decisão no teste de hipóteses","verso":"p-valor < α → rejeita H0. \"p baixo, H0 pro buraco.\""},{"id":"m13-f24","frente":"Erro tipo I × tipo II","verso":"I (α): alarme falso, \"grito sem lobo\". II (β): deixar passar, \"lobo sem grito\"."},{"id":"m13-f25","frente":"Correlação r e R²","verso":"r de −1 a +1 (força e sentido da relação linear). R² = r² = % explicada. Correlação ≠ causa."},{"id":"m13-f26","frente":"Reta de regressão","verso":"ŷ = a + b·x; b = Sxy ÷ Sxx; a = ȳ − b·x̄. Cuidado ao extrapolar."}],"formulas":{"m13-l2":[{"titulo":"Classes do histograma (Sturges)","texto":"k ≈ 1 + 3,322 · log₁₀(n)","nivel":"medio"}],"m13-l3":[{"titulo":"As três medidas de posição","texto":"**Média:** x̄ = Σx ÷ n (soma tudo, divide pela quantidade)","nivel":"facil"},{"titulo":"Média ponderada","texto":"**x̄ = Σ(x · peso) ÷ Σ(pesos)**","nivel":"facil"},{"titulo":"Média geométrica","texto":"G = [(1 + r₁)·(1 + r₂)·…·(1 + rₙ)]^(1/n) − 1","nivel":"medio"},{"titulo":"Média harmônica","texto":"H = n ÷ Σ(1 ÷ xᵢ)","nivel":"medio"}],"m13-l4":[{"titulo":"IQR e outliers (regra de Tukey)","texto":"**IQR = Q3 − Q1** (onde estão os 50% centrais)","nivel":"facil"},{"titulo":"Percentil (posição aproximada)","texto":"Posição ≈ p × (n + 1) nos dados ordenados; interpole entre vizinhos se cair entre dois.","nivel":"medio"}],"m13-l5":[{"titulo":"Medidas de dispersão","texto":"**Amplitude:** A = máximo − mínimo","nivel":"facil"},{"titulo":"Coeficiente de variação","texto":"**CV = s ÷ x̄ × 100%**","nivel":"facil"},{"titulo":"Soma de variâncias","texto":"σ²_total = σ₁² + σ₂² + … + σₙ² (variáveis independentes)","nivel":"medio"},{"titulo":"σ pelas amplitudes","texto":"σ̂ = R̄ ÷ d₂  (d₂ = 1,128 para n = 2; 2,059 para n = 4; 2,326 para n = 5)","nivel":"dificil"},{"titulo":"Função perda de Taguchi","texto":"L(y) = k · (y − m)²  ;  perda média = k·[σ² + (μ − m)²]","nivel":"dificil"}],"m13-l6":[{"titulo":"Custo do sobreenchimento","texto":"Custo = (μ − nominal) × pacotes × custo por grama","nivel":"dificil"}],"m13-l7":[{"titulo":"Regras básicas","texto":"**P(A)** = favoráveis ÷ possíveis (de 0 a 1)","nivel":"facil"},{"titulo":"Binomial","texto":"n tentativas, probabilidade p de \"sucesso\" (ex.: peça defeituosa).","nivel":"facil"},{"titulo":"Poisson","texto":"Eventos num intervalo de tempo, com taxa média λ.","nivel":"facil"},{"titulo":"Redundância (paralelo)","texto":"R_paralelo = 1 − (1 − R₁)·(1 − R₂)·…","nivel":"medio"},{"titulo":"Probabilidade condicional","texto":"P(A | B) = P(A e B) ÷ P(B)","nivel":"medio"},{"titulo":"Teorema de Bayes","texto":"P(D | alarme) = P(alarme | D)·P(D) ÷ [P(alarme | D)·P(D) + P(alarme | não D)·P(não D)]","nivel":"dificil"}],"m13-l8":[{"titulo":"Escore Z","texto":"**Z = (x − μ) ÷ σ**","nivel":"facil"},{"titulo":"Tabela Z para decorar","texto":"Cauda acima de Z:","nivel":"facil"},{"titulo":"Do percentil ao valor","texto":"x = μ + z · σ","nivel":"medio"}],"m13-l9":[{"titulo":"Erro padrão","texto":"**EP = σ ÷ √n** (ou s ÷ √n)","nivel":"facil"},{"titulo":"Intervalo de confiança (IC)","texto":"**IC = x̄ ± z · s ÷ √n**","nivel":"facil"},{"titulo":"Tamanho de amostra","texto":"**n = (z · σ ÷ E)²** (arredonde **para cima**)","nivel":"facil"},{"titulo":"IC para proporção","texto":"p̂ ± z · √(p̂ · (1 − p̂) ÷ n)","nivel":"medio"},{"titulo":"Tamanho de amostra para proporção","texto":"n = z² · p · (1 − p) ÷ E²  (sem ideia de p: use p = 0,5)","nivel":"medio"},{"titulo":"População finita","texto":"Erro padrão corrigido = (σ ÷ √n) · √((N − n) ÷ (N − 1))  (use quando n > 5% de N)","nivel":"dificil"}],"m13-l10":[{"titulo":"Teste para proporção","texto":"z = (p̂ − p₀) ÷ √(p₀ · (1 − p₀) ÷ n)","nivel":"medio"}],"m13-l11":[{"titulo":"Correlação de Pearson (r)","texto":"Mede a força da relação **linear**, de −1 a +1.","nivel":"facil"},{"titulo":"Regressão linear simples","texto":"**ŷ = a + b·x**","nivel":"facil"},{"titulo":"Coeficiente de correlação","texto":"r = Sxy ÷ √(Sxx · Syy)","nivel":"medio"}]}},"m02":{"glossario":[{"termo":"Projeto","definicao":"Esforço temporário empreendido para criar um produto, serviço ou resultado único (Guia PMBOK)."},{"termo":"Operação","definicao":"Trabalho contínuo e repetitivo que sustenta o negócio."},{"termo":"Patrocinador","definicao":"Quem financia e responde pelo projeto na organização; emite o TAP e decide nos conflitos maiores."},{"termo":"Parte interessada (stakeholder)","definicao":"Pessoa, grupo ou organização que afeta, é afetada ou se percebe afetada pelo projeto."},{"termo":"TAP (Termo de Abertura do Projeto)","definicao":"Documento que autoriza formalmente o projeto e dá ao gerente autoridade para usar recursos."},{"termo":"Premissa","definicao":"Algo considerado verdadeiro sem comprovação; é fonte potencial de risco."},{"termo":"Restrição","definicao":"Limite imposto ao projeto (prazo, orçamento, janela de parada, norma)."},{"termo":"Objetivo SMART","definicao":"Objetivo específico, mensurável, atingível, relevante e com prazo."},{"termo":"Matriz RACI","definicao":"Define para cada atividade quem é Responsável, Aprovador (um só), Consultado e Informado."},{"termo":"Escopo do produto","definicao":"Características e funções do que será entregue."},{"termo":"Escopo do projeto","definicao":"Trabalho necessário para entregar o produto com as características especificadas."},{"termo":"EAP (WBS)","definicao":"Decomposição hierárquica de todo o trabalho do projeto, orientada a entregas."},{"termo":"Pacote de trabalho","definicao":"Último nível da EAP, onde se estimam custo e duração e se atribui um responsável."},{"termo":"Regra dos 100%","definicao":"A EAP contém todo o trabalho do projeto (inclusive o gerenciamento) e nada além."},{"termo":"Linha de base","definicao":"Versão aprovada do escopo, cronograma ou custos, usada como referência para medir desvios."},{"termo":"Scope creep","definicao":"Crescimento descontrolado do escopo, sem ajuste de prazo, custo e riscos."},{"termo":"Gold plating","definicao":"Entregar mais do que o combinado por iniciativa da equipe, sem solicitação."},{"termo":"Caminho crítico","definicao":"Sequência mais longa de atividades dependentes; define a duração do projeto; folga total zero."},{"termo":"Folga total","definicao":"Quanto uma atividade pode atrasar sem atrasar o projeto (LS − ES)."},{"termo":"Folga livre","definicao":"Quanto uma atividade pode atrasar sem atrasar nenhum sucessor (menor ES dos sucessores − EF)."},{"termo":"ES, EF, LS, LF","definicao":"Início e término mais cedo; início e término mais tarde, calculados no CPM."},{"termo":"Lag e lead","definicao":"Lag: espera entre atividades dependentes. Lead: antecipação do sucessor."},{"termo":"PERT","definicao":"Técnica de três pontos: te = (a + 4m + b) ÷ 6 e σ = (b − a) ÷ 6."},{"termo":"Crashing","definicao":"Comprimir o cronograma adicionando recursos às atividades críticas; aumenta o custo."},{"termo":"Fast tracking","definicao":"Comprimir o cronograma fazendo em paralelo atividades antes sequenciais; aumenta o risco."},{"termo":"Viés de convergência","definicao":"Tendência do PERT de subestimar o prazo quando vários caminhos paralelos incertos convergem."},{"termo":"Risco","definicao":"Evento incerto que, se ocorrer, afeta os objetivos do projeto; pode ser ameaça ou oportunidade."},{"termo":"VME","definicao":"Valor monetário esperado: probabilidade × impacto."},{"termo":"Reserva de contingência","definicao":"Recursos para riscos identificados; faz parte da linha de base de custos."},{"termo":"Reserva gerencial","definicao":"Recursos para trabalho não identificado; fora da linha de base, liberada pela direção."},{"termo":"PV, EV, AC","definicao":"Valor planejado, valor agregado (trabalho feito valorizado pelo orçamento) e custo real."},{"termo":"CPI e SPI","definicao":"Índices de desempenho de custo (EV ÷ AC) e de prazo (EV ÷ PV)."},{"termo":"BAC, EAC, ETC, VAC","definicao":"Orçamento no término, estimativa no término, estimativa para terminar e variação no término."},{"termo":"TCPI","definicao":"Eficiência de custo necessária no restante do projeto para cumprir uma meta de custo: (BAC − EV) ÷ (BAC − AC)."},{"termo":"Manifesto Ágil","definicao":"Declaração de 2001 com 4 valores e 12 princípios para desenvolvimento ágil."},{"termo":"Product Owner","definicao":"Responsável por maximizar o valor do produto e ordenar o Product Backlog."},{"termo":"Scrum Master","definicao":"Responsável pela eficácia do time Scrum, ensinando e facilitando o uso do Scrum."},{"termo":"Sprint","definicao":"Ciclo de duração fixa, de até um mês, que contém os demais eventos do Scrum."},{"termo":"Definição de Pronto","definicao":"Padrão de qualidade que todo incremento precisa atender."},{"termo":"Velocidade","definicao":"Pontos concluídos por sprint; serve para previsão do próprio time, não como meta."},{"termo":"WIP","definicao":"Trabalho em progresso: itens começados e ainda não terminados."},{"termo":"Lead time e cycle time","definicao":"Lead: do pedido à entrega. Cycle: do início do trabalho à entrega."},{"termo":"Throughput","definicao":"Quantidade de itens entregues por unidade de tempo."},{"termo":"Lei de Little","definicao":"Em sistema estável: WIP médio = throughput × lead time médio."},{"termo":"CFD","definicao":"Diagrama de fluxo cumulativo: mostra o acúmulo de itens por etapa ao longo do tempo."}],"flashcards":[{"id":"m02-f01","frente":"Projeto é TUP","verso":"Temporário, Único e de elaboração Progressiva."},{"id":"m02-f02","frente":"Projeto × operação × processo","verso":"Projeto: temporário e único. Operação: contínua e repetitiva. Processo: atividades que transformam entradas em saídas (existe nos dois)."},{"id":"m02-f03","frente":"5 grupos de processos (PMBOK 6ª)","verso":"Iniciação, Planejamento, Execução, Monitoramento e Controle, Encerramento."},{"id":"m02-f04","frente":"PMBOK 7ª edição","verso":"12 princípios e 8 domínios de desempenho, orientados a valor."},{"id":"m02-f05","frente":"Para que serve o TAP?","verso":"Autorizar formalmente o projeto e dar autoridade ao GP. Assinado pelo patrocinador."},{"id":"m02-f06","frente":"Matriz poder × interesse","verso":"Alto/alto: gerenciar de perto. Alto poder: manter satisfeito. Alto interesse: manter informado. Baixo/baixo: monitorar."},{"id":"m02-f07","frente":"RACI","verso":"Responsável, Aprovador (só um), Consultado (antes), Informado (depois)."},{"id":"m02-f08","frente":"Premissa × restrição","verso":"Premissa: suposição não comprovada (vira risco). Restrição: limite imposto."},{"id":"m02-f09","frente":"Regra dos 100% da EAP","verso":"Todo o trabalho do projeto (inclusive gerenciamento), nada a mais e nada a menos."},{"id":"m02-f10","frente":"Scope creep × gold plating","verso":"Scope creep: escopo cresce sem controle. Gold plating: equipe entrega a mais por conta própria."},{"id":"m02-f11","frente":"CPM: ida e volta","verso":"Ida pega o MAIOR EF dos predecessores; volta pega o MENOR LS dos sucessores."},{"id":"m02-f12","frente":"Folga total × folga livre","verso":"Total: LS − ES (não atrasa o projeto). Livre: menor ES dos sucessores − EF (não atrasa ninguém)."},{"id":"m02-f13","frente":"PERT: te e σ","verso":"te = (a + 4m + b) ÷ 6; σ = (b − a) ÷ 6. No caminho, somam-se as variâncias."},{"id":"m02-f14","frente":"Prometer o Te do projeto dá quanto de chance?","verso":"Cerca de 50%."},{"id":"m02-f15","frente":"Crashing × fast tracking","verso":"Crashing: mais recurso, mais custo. Fast tracking: paralelizar, mais risco."},{"id":"m02-f16","frente":"Viés de convergência","verso":"PERT subestima o prazo quando há caminhos paralelos quase críticos. Solução: Monte Carlo."},{"id":"m02-f17","frente":"Formato de um risco","verso":"Devido a [causa], pode ocorrer [evento], o que causaria [efeito]."},{"id":"m02-f18","frente":"Respostas a ameaças","verso":"Evitar, transferir, mitigar, aceitar, escalar."},{"id":"m02-f19","frente":"Respostas a oportunidades","verso":"Explorar, compartilhar, melhorar, aceitar, escalar."},{"id":"m02-f20","frente":"VME","verso":"Probabilidade × impacto."},{"id":"m02-f21","frente":"Contingência × gerencial","verso":"Contingência: riscos identificados, dentro da linha de base. Gerencial: desconhecidos, fora dela."},{"id":"m02-f22","frente":"PV, EV, AC","verso":"Planejei, Entreguei, Achei na conta."},{"id":"m02-f23","frente":"CPI e SPI","verso":"CPI = EV ÷ AC; SPI = EV ÷ PV. Abaixo de 1 = ruim."},{"id":"m02-f24","frente":"EAC (desempenho continua)","verso":"EAC = BAC ÷ CPI; ETC = EAC − AC; VAC = BAC − EAC."},{"id":"m02-f25","frente":"TCPI","verso":"(BAC − EV) ÷ (BAC − AC): eficiência necessária no restante."},{"id":"m02-f26","frente":"Por que o SPI engana no fim?","verso":"Tende a 1 quando tudo termina, mesmo com atraso. Use Earned Schedule."},{"id":"m02-f27","frente":"4 valores do Manifesto Ágil","verso":"Indivíduos e interações; software funcionando; colaboração com o cliente; responder a mudanças."},{"id":"m02-f28","frente":"Scrum 3-5-3","verso":"PO, SM, Developers; Sprint, Planning, Daily, Review, Retro; Product Backlog, Sprint Backlog, Incremento."},{"id":"m02-f29","frente":"Compromissos dos artefatos Scrum","verso":"Meta do Produto, Meta da Sprint, Definição de Pronto."},{"id":"m02-f30","frente":"Lei de Little","verso":"WIP = throughput × lead time (médias, sistema estável)."},{"id":"m02-f31","frente":"Lead time × cycle time","verso":"Lead: do pedido à entrega. Cycle: do início do trabalho à entrega."},{"id":"m02-f32","frente":"Lei de Goodhart","verso":"Quando uma medida vira meta, deixa de ser uma boa medida."}],"formulas":{"m02-l4":[{"titulo":"Método do caminho crítico (CPM)","texto":"**Ida (forward pass):** ES = maior EF entre os predecessores (0 no início); EF = ES + d.","nivel":"medio"},{"titulo":"Folga livre × folga total","texto":"**Folga total** = LS − ES: quanto a atividade pode atrasar **sem atrasar o projeto**.","nivel":"dificil"}],"m02-l5":[{"titulo":"Duração esperada (PERT)","texto":"**te = (a + 4m + b) ÷ 6**","nivel":"facil"},{"titulo":"Incerteza no PERT","texto":"**σ = (b − a) ÷ 6** · variância = σ²","nivel":"medio"},{"titulo":"Custo de compressão por dia","texto":"**Custo/dia = (custo acelerado − custo normal) ÷ (duração normal − duração acelerada)**","nivel":"medio"}],"m02-l6":[{"titulo":"Valor monetário esperado","texto":"**VME = P × impacto** (ameaça com sinal negativo; oportunidade positivo).","nivel":"medio"}],"m02-l7":[{"titulo":"Variações e índices","texto":"**CV = EV − AC** (custo) · **SV = EV − PV** (prazo, em R$)","nivel":"medio"},{"titulo":"Projeções","texto":"**EAC = BAC ÷ CPI** (se o desempenho de custo continuar)","nivel":"medio"},{"titulo":"Qual EAC usar?","texto":"**1) EAC = AC + (BAC − EV):** o desvio foi **atípico** (não se repete); o resto segue o plano.","nivel":"dificil"},{"titulo":"TCPI: a eficiência necessária","texto":"**TCPI = (BAC − EV) ÷ (BAC − AC)**: eficiência de custo necessária no **restante** para terminar dentro do BAC.","nivel":"dificil"}],"m02-l8":[{"titulo":"Previsão por velocidade","texto":"**Sprints restantes = pontos restantes ÷ velocidade média**","nivel":"medio"}],"m02-l9":[{"titulo":"Lei de Little","texto":"**WIP = throughput × lead time** (L = λW)","nivel":"medio"}]}},"m04":{"glossario":[{"termo":"Estudo do trabalho","definicao":"Conjunto de estudo de métodos (como fazer) e medida do trabalho (quanto tempo)."},{"termo":"Fluxograma de processo","definicao":"Registro sequencial das etapas com os símbolos operação, transporte, inspeção, espera e armazenagem."},{"termo":"ECRS","definicao":"Eliminar, Combinar, Rearranjar, Simplificar: ordem de ataque das melhorias de método."},{"termo":"Therbligs","definicao":"Micromovimentos do trabalho manual definidos pelos Gilbreth (procurar, pegar, posicionar…)."},{"termo":"Diagrama de espaguete","definicao":"Desenho do caminho real percorrido por pessoas ou materiais sobre a planta."},{"termo":"Cronoanálise","definicao":"Medição de tempos com cronômetro de uma operação padronizada, dividida em elementos."},{"termo":"Elemento","definicao":"Parte de uma operação com início e fim observáveis."},{"termo":"Elemento estranho","definicao":"Evento que não faz parte do método normal (peça que cai, conversa); registrado à parte."},{"termo":"Tempo observado (TO)","definicao":"Média dos tempos cronometrados."},{"termo":"Fator de ritmo","definicao":"Avaliação do ritmo do operador em relação ao normal (100%)."},{"termo":"Tempo normal (TN)","definicao":"TO × fator de ritmo: tempo de um operador qualificado em ritmo normal."},{"termo":"Tolerâncias","definicao":"Acréscimos para necessidades pessoais, fadiga e esperas inevitáveis."},{"termo":"Tempo padrão (TP)","definicao":"Tempo normal acrescido das tolerâncias."},{"termo":"Amostragem do trabalho","definicao":"Observações instantâneas aleatórias para estimar a porcentagem de tempo em cada atividade."},{"termo":"MTM / MOST","definicao":"Sistemas de tempos predeterminados baseados em micromovimentos tabelados."},{"termo":"TMU","definicao":"Unidade de tempo do MTM: 0,00001 hora = 0,036 s."},{"termo":"Horas-padrão","definicao":"Quantidade produzida × tempo padrão."},{"termo":"Eficiência","definicao":"Horas-padrão produzidas ÷ horas trabalhadas."},{"termo":"Utilização","definicao":"Horas trabalhadas ÷ horas disponíveis."},{"termo":"Curva de aprendizagem","definicao":"Queda do tempo por unidade a uma taxa fixa a cada dobro da produção acumulada (Wright, 1936)."},{"termo":"Takt time","definicao":"Tempo disponível ÷ demanda: ritmo que o cliente exige."},{"termo":"Tempo de ciclo","definicao":"Ritmo real da linha, dado pelo maior tempo entre os postos."},{"termo":"Balanceamento de linha","definicao":"Distribuição das tarefas entre postos respeitando precedência e takt."},{"termo":"Diagrama de precedência","definicao":"Rede que mostra quais tarefas precisam ser feitas antes de outras."},{"termo":"Eficiência do balanceamento","definicao":"Σt ÷ (N × TC)."},{"termo":"Ociosidade","definicao":"N × TC − Σt: tempo parado por ciclo somando todos os postos."},{"termo":"Postos em paralelo","definicao":"Dois ou mais operadores fazendo a mesma tarefa em unidades alternadas."},{"termo":"Gargalo","definicao":"Recurso que limita a saída do sistema; na linha, o posto de maior tempo."},{"termo":"Teoria das Restrições (TOC)","definicao":"Abordagem de Goldratt: identificar, explorar, subordinar, elevar e repetir."},{"termo":"Tambor-pulmão-corda","definicao":"Programação pela TOC: o gargalo dita o ritmo, o pulmão o protege e a corda controla a liberação."}],"flashcards":[{"id":"m04-f01","frente":"Estudo do trabalho = ?","verso":"Estudo de métodos (como) + medida do trabalho (quanto tempo). Método primeiro."},{"id":"m04-f02","frente":"5 símbolos do fluxograma","verso":"Operação, Transporte, Inspeção, Espera, Armazenagem (“O Tio Ignorou a Espera no Armazém”)."},{"id":"m04-f03","frente":"ECRS","verso":"Eliminar, Combinar, Rearranjar, Simplificar."},{"id":"m04-f04","frente":"Therbligs ineficientes","verso":"Procurar, selecionar, segurar, esperar."},{"id":"m04-f05","frente":"Número de ciclos da cronoanálise","verso":"n = (z · s ÷ (Er · x̄))², arredondando para cima."},{"id":"m04-f06","frente":"Leitura contínua × repetitiva","verso":"Contínua: não zera, subtrai depois. Repetitiva: zera a cada elemento."},{"id":"m04-f07","frente":"TO → TN → TP","verso":"TN = TO × ritmo; TP = TN × (1 + T) ou TN ÷ (1 − T)."},{"id":"m04-f08","frente":"Ritmo acima de 100%","verso":"Operador rápido: TN maior que o TO."},{"id":"m04-f09","frente":"Tipos de tolerância","verso":"Pessoais, fadiga, esperas inevitáveis."},{"id":"m04-f10","frente":"Capacidade por turno","verso":"Tempo disponível ÷ TP, arredondado para baixo."},{"id":"m04-f11","frente":"Amostragem do trabalho","verso":"n = z² · p(1 − p) ÷ E². Observações instantâneas aleatórias."},{"id":"m04-f12","frente":"Tempos predeterminados","verso":"MTM, MOST: tempos tabelados de micromovimentos; servem antes de a linha existir."},{"id":"m04-f13","frente":"Eficiência × utilização","verso":"Eficiência: horas-padrão ÷ horas trabalhadas. Utilização: trabalhadas ÷ disponíveis."},{"id":"m04-f14","frente":"Curva de aprendizagem 80%","verso":"A cada DOBRO da produção acumulada, o tempo cai para 80%."},{"id":"m04-f15","frente":"Takt time","verso":"Tempo disponível ÷ demanda. “Takt é o cliente, ciclo é a linha.”"},{"id":"m04-f16","frente":"N mínimo de postos","verso":"⌈Σt ÷ takt⌉ — é um limite inferior."},{"id":"m04-f17","frente":"Heurística do maior tempo","verso":"Entre as tarefas liberadas que cabem no posto, escolha a mais longa."},{"id":"m04-f18","frente":"Eficiência do balanceamento","verso":"Σt ÷ (N × TC). Ociosidade = N × TC − Σt."},{"id":"m04-f19","frente":"Tarefa maior que o takt","verso":"Dividir, postos em paralelo ou automatizar."},{"id":"m04-f20","frente":"Gargalo","verso":"Posto de maior tempo de ciclo; dita a saída. Melhorar fora dele não aumenta a produção."},{"id":"m04-f21","frente":"5 passos da TOC","verso":"Identificar, explorar, subordinar, elevar, repetir."},{"id":"m04-f22","frente":"Quando não investir no gargalo","verso":"Quando a restrição é o mercado (demanda menor que a capacidade)."}],"formulas":{"m04-l2":[{"titulo":"Quantos ciclos medir?","texto":"**n = (z · s ÷ (Er · x̄))²** (arredonde para cima)","nivel":"medio"},{"titulo":"Observações na amostragem do trabalho","texto":"**n = z² · p · (1 − p) ÷ E²**","nivel":"dificil"}],"m04-l3":[{"titulo":"Do observado ao padrão","texto":"**TN = TO × FR**","nivel":"facil"},{"titulo":"Duas convenções","texto":"**(a) TP = TN × (1 + T):** T aplicada sobre o tempo normal.","nivel":"medio"},{"titulo":"Capacidade por turno","texto":"**Capacidade = tempo disponível ÷ TP** (arredondada para **baixo**)","nivel":"medio"}],"m04-l4":[{"titulo":"Horas-padrão, eficiência e utilização","texto":"**Horas-padrão produzidas = peças × TP**","nivel":"facil"},{"titulo":"Curva de aprendizagem (Wright, 1936)","texto":"**Tn = T1 · n^b**, com **b = log(taxa) ÷ log 2**","nivel":"dificil"}],"m04-l5":[{"titulo":"Takt time","texto":"**Takt = tempo disponível ÷ demanda**","nivel":"facil"},{"titulo":"Número mínimo de postos","texto":"**N mínimo = Σt ÷ takt**, arredondado para **cima**.","nivel":"facil"},{"titulo":"Eficiência e ociosidade","texto":"**Eficiência = Σt ÷ (N × TC)** = 180 ÷ (4 × 55) = **81,8%**","nivel":"medio"}]}},"m03":{"glossario":[{"termo":"PCP","definicao":"Planejamento e Controle da Produção: decide o que, quanto, quando e onde produzir e controla a execução."},{"termo":"Planejamento estratégico da produção","definicao":"Nível de longo prazo: capacidade, fábricas e grandes investimentos."},{"termo":"MTS","definicao":"Make to stock: produzir para estoque, antes do pedido."},{"termo":"ATO","definicao":"Assemble to order: fabricar módulos antes e montar no pedido."},{"termo":"MTO","definicao":"Make to order: fabricar depois do pedido."},{"termo":"ETO","definicao":"Engineer to order: projetar e fabricar depois do pedido."},{"termo":"Ponto de desacoplamento","definicao":"Ponto da cadeia que separa a produção por previsão da produção por pedido."},{"termo":"S&OP","definicao":"Sales and Operations Planning: processo mensal que integra as áreas num plano único por família."},{"termo":"Método Delphi","definicao":"Previsão qualitativa por rodadas anônimas de especialistas até o consenso."},{"termo":"Média móvel simples","definicao":"Média dos últimos n períodos usada como previsão."},{"termo":"Média móvel ponderada","definicao":"Média com pesos maiores para os períodos recentes; os pesos somam 1."},{"termo":"Suavização exponencial","definicao":"Fₜ₊₁ = Fₜ + α(Aₜ − Fₜ): corrige a previsão por uma fração do erro."},{"termo":"Tendência","definicao":"Movimento persistente de alta ou de baixa da série."},{"termo":"Sazonalidade","definicao":"Padrão que se repete em intervalos regulares."},{"termo":"Índice sazonal","definicao":"Razão entre a média do período e a média geral."},{"termo":"MAD","definicao":"Desvio absoluto médio dos erros de previsão."},{"termo":"MAPE","definicao":"Erro percentual absoluto médio."},{"termo":"MSE","definicao":"Erro quadrático médio; pune erros grandes."},{"termo":"Sinal de rastreamento","definicao":"Soma dos erros ÷ MAD; detecta viés da previsão."},{"termo":"Holt-Winters","definicao":"Suavização exponencial com nível, tendência e sazonalidade."},{"termo":"Planejamento agregado","definicao":"Plano por família de produtos e por mês: produção, pessoas, estoque."},{"termo":"Estratégia de acompanhamento (chase)","definicao":"Produção acompanha a demanda período a período."},{"termo":"Produção nivelada (level)","definicao":"Produção constante; o estoque absorve a variação da demanda."},{"termo":"PMP / MPS","definicao":"Plano mestre: quanto de cada produto final em cada período."},{"termo":"ATP","definicao":"Available to promise: quantidade ainda disponível para prometer a novos pedidos."},{"termo":"Zona congelada","definicao":"Horizonte do PMP em que o plano não deve ser alterado."},{"termo":"BOM","definicao":"Bill of materials: lista de materiais com componentes e quantidades."},{"termo":"Demanda dependente","definicao":"Demanda de um item calculada a partir da de outro (seu pai na BOM)."},{"termo":"MRP","definicao":"Material Requirements Planning: cálculo das necessidades de materiais."},{"termo":"Necessidade líquida","definicao":"Necessidade bruta menos estoque e recebimentos programados (mais estoque de segurança)."},{"termo":"Recebimento programado","definicao":"Ordem já emitida, com data de chegada prevista."},{"termo":"Lote a lote","definicao":"Regra que pede exatamente a necessidade líquida."},{"termo":"MRP II","definicao":"Manufacturing Resource Planning: MRP com capacidade, custos e integração."},{"termo":"ERP","definicao":"Sistema integrado de gestão de toda a empresa."},{"termo":"Nervosismo do MRP","definicao":"Mudanças frequentes nas ordens planejadas a cada replanejamento."},{"termo":"Capacidade projetada","definicao":"Máximo teórico de produção, sem paradas."},{"termo":"Capacidade efetiva","definicao":"Capacidade projetada menos as perdas planejadas."},{"termo":"Capacidade realizada","definicao":"Produção obtida de fato."},{"termo":"RCCP","definicao":"Verificação grosseira da capacidade do PMP nos recursos críticos."},{"termo":"CRP","definicao":"Verificação detalhada da capacidade a partir das ordens do MRP."},{"termo":"PEPS","definicao":"Primeiro que entra, primeiro que sai (FIFO)."},{"termo":"MTP","definicao":"Menor tempo de processamento primeiro (SPT)."},{"termo":"DD","definicao":"Menor data de entrega primeiro (EDD)."},{"termo":"Regra de Johnson","definicao":"Sequenciamento ótimo (makespan) para duas máquinas em série."},{"termo":"Makespan","definicao":"Tempo total para terminar todas as tarefas."},{"termo":"Lei de Little","definicao":"WIP = taxa de saída × lead time."},{"termo":"OTIF","definicao":"On time in full: entregas no prazo e completas."}],"flashcards":[{"id":"m03-f01","frente":"4 perguntas do PCP","verso":"O que, quanto, quando e onde produzir (e depois controlar)."},{"id":"m03-f02","frente":"3 níveis do planejamento","verso":"Estratégico (anos), tático (meses), operacional (dias/horas)."},{"id":"m03-f03","frente":"MTS → ATO → MTO → ETO","verso":"“Estoque, Monta, Faz, Projeta”: cliente espera mais, empresa guarda menos."},{"id":"m03-f04","frente":"S&OP","verso":"Processo mensal que integra vendas, produção, compras e finanças num plano único."},{"id":"m03-f05","frente":"Média móvel simples","verso":"Média dos últimos n períodos. n grande = suave e lenta."},{"id":"m03-f06","frente":"Suavização exponencial","verso":"Fₜ₊₁ = Fₜ + α(Aₜ − Fₜ). α grande = reage rápido."},{"id":"m03-f07","frente":"Médias com tendência","verso":"Ficam atrasadas: erro sempre do mesmo lado (viés)."},{"id":"m03-f08","frente":"MAD × MAPE × MSE","verso":"MAD: unidade. MAPE: %, compara itens. MSE: pune erros grandes."},{"id":"m03-f09","frente":"Sinal de rastreamento","verso":"Σ erros ÷ MAD; fora de ±4 (usual) indica viés."},{"id":"m03-f10","frente":"Índice sazonal 1,2","verso":"Período 20% acima da média. Previsão = base × índice."},{"id":"m03-f11","frente":"Acompanhar × nivelar","verso":"Acompanhar: produção varia, pouco estoque. Nivelar: produção fixa, estoque varia."},{"id":"m03-f12","frente":"Agregado × PMP","verso":"“Agregado agrupa (família × mês), Mestre detalha (produto × semana).”"},{"id":"m03-f13","frente":"ATP","verso":"Disponível para promessa: PMP (+ estoque no 1º período) − pedidos até o próximo PMP."},{"id":"m03-f14","frente":"Demanda dependente","verso":"Calculada a partir do pai na BOM; não se prevê."},{"id":"m03-f15","frente":"Necessidade líquida","verso":"NB − estoque − recebimentos programados (+ ES), nunca negativa."},{"id":"m03-f16","frente":"Liberação da ordem","verso":"Recebimento planejado recuado do lead time."},{"id":"m03-f17","frente":"Premissas do MRP","verso":"Capacidade infinita e lead time fixo; exige dados exatos."},{"id":"m03-f18","frente":"Utilização × eficiência (Slack)","verso":"Utilização = realizada ÷ projetada. Eficiência = realizada ÷ efetiva."},{"id":"m03-f19","frente":"RCCP × CRP","verso":"RCCP: grosseiro, PMP, recursos críticos. CRP: detalhado, ordens do MRP."},{"id":"m03-f20","frente":"MTP × DD","verso":"MTP minimiza o fluxo médio; DD minimiza o maior atraso (uma máquina)."},{"id":"m03-f21","frente":"Regra de Johnson","verso":"Menor tempo em M1 → início; em M2 → fim. Minimiza o makespan (2 máquinas)."},{"id":"m03-f22","frente":"Lei de Little","verso":"WIP = taxa × lead time."}],"formulas":{"m03-l2":[{"titulo":"Média móvel simples (MMS)","texto":"Fₜ₊₁ = (Aₜ + Aₜ₋₁ + … + Aₜ₋ₙ₊₁) ÷ n","nivel":"facil"},{"titulo":"Média móvel ponderada","texto":"Fₜ₊₁ = Σ wᵢ · Aᵢ   com Σ wᵢ = 1","nivel":"medio"},{"titulo":"Suavização exponencial simples","texto":"Fₜ₊₁ = Fₜ + α · (Aₜ − Fₜ)   ou   Fₜ₊₁ = α · Aₜ + (1 − α) · Fₜ","nivel":"medio"}],"m03-l3":[{"titulo":"Erro e MAD","texto":"eₜ = Aₜ − Fₜ","nivel":"facil"},{"titulo":"MAPE e MSE","texto":"MAPE = (Σ |eₜ| ÷ Aₜ) ÷ n × 100%","nivel":"medio"},{"titulo":"Regressão linear para tendência","texto":"F = a + b · x","nivel":"medio"},{"titulo":"Sinal de rastreamento (tracking signal)","texto":"TS = Σ eₜ ÷ MAD","nivel":"dificil"}],"m03-l4":[{"titulo":"Estoque projetado no PMP","texto":"Eₜ = Eₜ₋₁ + PMPₜ − max(Previsãoₜ, Pedidosₜ)","nivel":"medio"}],"m03-l5":[{"titulo":"Necessidade bruta","texto":"NB(componente) = quantidade planejada do pai × quantidade por unidade","nivel":"facil"},{"titulo":"Necessidade líquida","texto":"NL = max(0; NB − Estoque disponível − Recebimentos programados + Estoque de segurança)","nivel":"medio"}],"m03-l6":[{"titulo":"Capacidade em horas","texto":"Capacidade = nº de recursos × horas por turno × turnos por dia × dias","nivel":"facil"},{"titulo":"Utilização e eficiência (Slack)","texto":"Utilização = produção realizada ÷ capacidade projetada","nivel":"medio"},{"titulo":"Carga × capacidade","texto":"Carga = Σ (quantidade do item × tempo padrão do item)","nivel":"medio"}],"m03-l7":[{"titulo":"Indicadores de sequenciamento","texto":"Tempo de fluxo = término − liberação","nivel":"medio"}]}},"m06":{"glossario":[{"termo":"Lean","definicao":"Sistema de gestão que busca entregar valor ao cliente com o mínimo de desperdício."},{"termo":"Sistema Toyota de Produção (STP/TPS)","definicao":"Sistema desenvolvido na Toyota por Taiichi Ohno; origem do Lean."},{"termo":"Cinco princípios","definicao":"Valor, fluxo de valor, fluxo, puxar e perfeição (Womack e Jones)."},{"termo":"Just in time (JIT)","definicao":"Item certo, na quantidade certa, no momento certo; pilar do TPS."},{"termo":"Jidoka","definicao":"Automação com toque humano: detectar a anormalidade, parar e corrigir; pilar do TPS."},{"termo":"Muda","definicao":"Desperdício."},{"termo":"Mura","definicao":"Irregularidade, variação."},{"termo":"Muri","definicao":"Sobrecarga de pessoas ou equipamentos."},{"termo":"TIM WOODS","definicao":"Mnemônico dos 8 desperdícios: transporte, inventário, movimentação, espera, superprodução, superprocessamento, defeitos, talento."},{"termo":"Superprodução","definicao":"Produzir antes ou mais do que o necessário; considerado o pior desperdício."},{"termo":"Atividade que agrega valor","definicao":"Transforma o produto, o cliente paga por ela e é feita certa da primeira vez."},{"termo":"NNAV","definicao":"Atividade necessária que não agrega valor; deve ser reduzida."},{"termo":"5S","definicao":"Seiri, Seiton, Seiso, Seiketsu, Shitsuke: utilização, ordenação, limpeza, padronização e disciplina."},{"termo":"Gestão visual","definicao":"Tornar a situação e as anormalidades visíveis de relance."},{"termo":"Andon","definicao":"Sinal luminoso ou sonoro que indica um problema na linha."},{"termo":"Trabalho padronizado","definicao":"Melhor forma atual de fazer a operação: takt, sequência e estoque padrão em processo."},{"termo":"Gemba","definicao":"O lugar onde o trabalho acontece."},{"termo":"Produção empurrada","definicao":"Produzir conforme o plano, independentemente do consumo do processo seguinte."},{"termo":"Produção puxada","definicao":"Produzir apenas para repor o que foi consumido."},{"termo":"Kanban","definicao":"Cartão ou sinal que autoriza produzir ou movimentar."},{"termo":"Supermercado","definicao":"Estoque controlado, reposto por kanban, entre processos que não podem fluir continuamente."},{"termo":"FIFO lane","definicao":"Fila PEPS com limite máximo entre dois processos."},{"termo":"Fluxo contínuo","definicao":"Produção peça a peça, sem estoque entre processos."},{"termo":"CONWIP","definicao":"Sistema puxado que limita o WIP total de uma linha."},{"termo":"VSM","definicao":"Mapeamento do fluxo de valor: desenho do fluxo de material e informação, com linha do tempo."},{"termo":"Dias de estoque","definicao":"Estoque ÷ demanda diária."},{"termo":"PCE","definicao":"Eficiência do ciclo do processo: tempo de agregação de valor ÷ lead time."},{"termo":"Processo puxador","definicao":"Único processo que recebe a programação do cliente no estado futuro."},{"termo":"Setup","definicao":"Tempo da última peça boa de um produto até a primeira peça boa do seguinte."},{"termo":"Setup interno","definicao":"Parte do setup feita apenas com a máquina parada."},{"termo":"Setup externo","definicao":"Parte do setup que pode ser feita com a máquina rodando."},{"termo":"SMED","definicao":"Single-Minute Exchange of Die: método de Shingo para reduzir o setup."},{"termo":"EPEI","definicao":"Every part every interval: intervalo para produzir todos os produtos uma vez."},{"termo":"Heijunka","definicao":"Nivelamento do volume e do mix da produção."},{"termo":"Pitch","definicao":"Takt × quantidade por embalagem: intervalo de liberação de trabalho."},{"termo":"Poka-yoke","definicao":"Dispositivo ou método à prova de erro."},{"termo":"TPM","definicao":"Manutenção produtiva total: operadores e manutenção juntos pela confiabilidade do equipamento."},{"termo":"Manutenção autônoma","definicao":"Pilar do TPM em que o operador limpa, inspeciona e lubrifica o equipamento."},{"termo":"OEE","definicao":"Eficiência global do equipamento: disponibilidade × performance × qualidade."},{"termo":"Seis grandes perdas","definicao":"Quebras, setup/ajustes, pequenas paradas, velocidade reduzida, defeitos, perdas de partida."},{"termo":"Kaizen","definicao":"Melhoria contínua e incremental feita por todos."},{"termo":"Evento kaizen","definicao":"Equipe dedicada por alguns dias a um problema definido."},{"termo":"PDCA","definicao":"Planejar, Fazer, Checar, Agir: ciclo de melhoria."},{"termo":"A3","definicao":"Relatório de uma folha que estrutura a solução de um problema pela lógica do PDCA."},{"termo":"5 porquês","definicao":"Perguntar “por quê?” sucessivamente até chegar a uma causa acionável."}],"flashcards":[{"id":"m06-f01","frente":"5 princípios Lean","verso":"Valor, fluxo de valor, fluxo, puxar, perfeição (“Vale Fazer Fluir, Puxando a Perfeição”)."},{"id":"m06-f02","frente":"Pilares da casa do TPS","verso":"Just in time e jidoka."},{"id":"m06-f03","frente":"8 desperdícios","verso":"TIM WOODS: transporte, inventário, movimentação, espera, superprodução, superprocessamento, defeitos, talento."},{"id":"m06-f04","frente":"Pior desperdício","verso":"Superprodução: gera estoque, transporte, espera e esconde defeitos."},{"id":"m06-f05","frente":"Muda, mura, muri","verso":"Desperdício, irregularidade, sobrecarga. Mura → muri → muda."},{"id":"m06-f06","frente":"AV × NNAV × desperdício","verso":"Manter/melhorar · reduzir · eliminar."},{"id":"m06-f07","frente":"5S","verso":"Utilização, ordenação, limpeza, padronização, disciplina."},{"id":"m06-f08","frente":"Trabalho padronizado","verso":"Takt + sequência de trabalho + estoque padrão em processo."},{"id":"m06-f09","frente":"Empurrar × puxar","verso":"Empurrar: pelo plano. Puxar: repõe o consumido."},{"id":"m06-f10","frente":"Número de kanbans","verso":"N = D × L × (1 + α) ÷ C, arredondando para cima."},{"id":"m06-f11","frente":"Regras do kanban","verso":"Seguinte retira; anterior produz só o retirado; nada sem kanban; kanban junto; defeito não segue; reduzir kanbans."},{"id":"m06-f12","frente":"Rio e pedras","verso":"Estoque esconde problemas; baixe aos poucos e resolva as causas."},{"id":"m06-f13","frente":"VSM: dias de estoque","verso":"Estoque ÷ demanda diária."},{"id":"m06-f14","frente":"PCE","verso":"Tempo de agregação de valor ÷ lead time (quase sempre < 1%)."},{"id":"m06-f15","frente":"Etapas do SMED","verso":"Separar interno/externo, converter interno em externo, racionalizar (“Separa, Converte, Racionaliza”)."},{"id":"m06-f16","frente":"EPEI","verso":"Nº de produtos ÷ setups possíveis por dia."},{"id":"m06-f17","frente":"Pitch","verso":"Takt × quantidade por embalagem."},{"id":"m06-f18","frente":"Poka-yoke controle × advertência","verso":"Controle impede o erro; advertência avisa."},{"id":"m06-f19","frente":"OEE","verso":"D × P × Q = boas × ciclo ideal ÷ tempo planejado."},{"id":"m06-f20","frente":"Seis grandes perdas","verso":"D: quebras, setup · P: pequenas paradas, velocidade · Q: defeitos, partida."},{"id":"m06-f21","frente":"PDCA","verso":"Planejar, Fazer, Checar, Agir."},{"id":"m06-f22","frente":"A3","verso":"Contexto, situação atual, meta, causa, contramedidas, plano, acompanhamento."}],"formulas":{"m06-l4":[{"titulo":"Número de kanbans","texto":"N = D × L × (1 + α) ÷ C   (arredondar para cima)","nivel":"medio"}],"m06-l5":[{"titulo":"Dias de estoque","texto":"Dias de estoque = quantidade em estoque ÷ demanda diária do cliente","nivel":"facil"},{"titulo":"Lead time e eficiência do ciclo","texto":"Lead time ≈ Σ dias de estoque + Σ tempos de processo","nivel":"medio"}],"m06-l6":[{"titulo":"EPEI","texto":"Nº de setups possíveis por dia = tempo disponível para setups ÷ tempo de setup","nivel":"dificil"},{"titulo":"Pitch","texto":"Pitch = takt time × quantidade por embalagem","nivel":"dificil"}],"m06-l7":[{"titulo":"OEE","texto":"OEE = D × P × Q","nivel":"facil"}]}},"m14":{"glossario":[{"termo":"ERP","definicao":"Sistema de gestão empresarial: pedidos, estoques, compras, finanças."},{"termo":"MES","definicao":"Sistema de execução da manufatura: ordens, apontamentos, paradas, rastreabilidade."},{"termo":"CLP","definicao":"Controlador lógico programável: computador industrial que comanda máquinas."},{"termo":"SCADA","definicao":"Sistema de supervisão e aquisição de dados de equipamentos industriais."},{"termo":"IoT industrial","definicao":"Equipamentos e sensores conectados que enviam dados do processo."},{"termo":"Sistema ciberfísico","definicao":"Integração entre processo físico e sistema digital que monitora e atua."},{"termo":"Gêmeo digital","definicao":"Modelo digital atualizado com dados do ativo real, usado para simular e prever."},{"termo":"ISA-95","definicao":"Modelo de níveis que integra o chão de fábrica (controle) aos sistemas de negócio."},{"termo":"OPC UA","definicao":"Padrão aberto de comunicação industrial para interoperabilidade entre sistemas."},{"termo":"Rastreabilidade","definicao":"Capacidade de ligar cada lote aos insumos, processos e clientes."},{"termo":"Qualidade de dados","definicao":"Grau de completude, exatidão, consistência, atualidade, validade e unicidade dos dados."},{"termo":"Completude","definicao":"Proporção de registros preenchidos em relação ao esperado."},{"termo":"Dicionário de dados","definicao":"Documento com significado, unidade, formato e fonte de cada campo."},{"termo":"Linhagem de dados","definicao":"Registro da origem e das transformações de um dado até o relatório."},{"termo":"MCAR / MAR / MNAR","definicao":"Tipos de dados faltantes: totalmente ao acaso, ao acaso condicionado, não ao acaso."},{"termo":"LGPD","definicao":"Lei Geral de Proteção de Dados (Lei 13.709/2018), que regula dados pessoais."},{"termo":"Tidy data","definicao":"Organização em que cada variável é uma coluna e cada observação uma linha."},{"termo":"SOMASES / CONT.SES","definicao":"Funções que somam ou contam com vários critérios."},{"termo":"PROCX","definicao":"Função de busca que devolve o valor correspondente de outra coluna (substitui o PROCV)."},{"termo":"Tabela dinâmica","definicao":"Ferramenta que resume dados por grupos sem fórmulas."},{"termo":"OEE","definicao":"Eficiência global do equipamento: disponibilidade × performance × qualidade."},{"termo":"Paradoxo de Simpson","definicao":"Quando a tendência nos grupos se inverte ao agregar os dados, por efeito do mix."},{"termo":"Indicador de resultado × de processo","definicao":"Resultado mostra o que aconteceu; processo antecipa o resultado."},{"termo":"SQL","definicao":"Linguagem para consultar e manipular bancos de dados relacionais."},{"termo":"Chave primária / estrangeira","definicao":"Primária identifica a linha; estrangeira liga uma tabela a outra."},{"termo":"GROUP BY / HAVING","definicao":"Agrupa linhas para agregar; HAVING filtra os grupos depois da agregação."},{"termo":"JOIN","definicao":"Junção de tabelas por uma chave comum."},{"termo":"pandas","definicao":"Biblioteca Python para manipular tabelas de dados."},{"termo":"Modelo estrela","definicao":"Estrutura de BI com tabela fato no centro e dimensões ao redor."},{"termo":"Medida × coluna calculada","definicao":"Medida calcula conforme os filtros; coluna calculada, linha a linha."},{"termo":"Aprendizado supervisionado","definicao":"Modelo aprende com exemplos rotulados (classificação ou regressão)."},{"termo":"Matriz de confusão","definicao":"Tabela com verdadeiros/falsos positivos e negativos de um classificador."},{"termo":"Precisão e recall","definicao":"Precisão: VP ÷ (VP + FP). Recall: VP ÷ (VP + FN)."},{"termo":"Sobreajuste (overfitting)","definicao":"Modelo que decora o treino e generaliza mal."},{"termo":"Vazamento de dados","definicao":"Uso de informação que só existe depois do evento a prever."},{"termo":"Drift","definicao":"Mudança nos dados ou no processo que degrada o desempenho do modelo."}],"flashcards":[{"id":"m14-f01","frente":"Lixo entra…","verso":"…lixo sai. Qualidade de dados vem antes da análise."},{"id":"m14-f02","frente":"6 dimensões de qualidade de dados","verso":"Completude, exatidão, consistência, atualidade, validade, unicidade."},{"id":"m14-f03","frente":"Onde corrigir dados ruins?","verso":"Na origem: listas, faixas válidas, campos obrigatórios, registro automático."},{"id":"m14-f04","frente":"MNAR","verso":"Dado falta por causa do próprio valor (ex.: paradas por erro não apontadas). Gera viés."},{"id":"m14-f05","frente":"Governança mínima","verso":"Dono, dicionário, linhagem, fonte única."},{"id":"m14-f06","frente":"Tidy data","verso":"Cada variável uma coluna, cada observação uma linha."},{"id":"m14-f07","frente":"Armadilha do PROCV","verso":"Sem FALSO faz correspondência aproximada e erra em silêncio. Prefira PROCX."},{"id":"m14-f08","frente":"Porcentagem por grupo","verso":"Razão das somas, não média das razões."},{"id":"m14-f09","frente":"Ficha do indicador","verso":"Nome, objetivo, fórmula, unidade, fonte, frequência, dono, meta, polaridade."},{"id":"m14-f10","frente":"OEE","verso":"Disponibilidade × Performance × Qualidade, sobre o tempo planejado."},{"id":"m14-f11","frente":"Paradoxo de Simpson","verso":"O total pode inverter a conclusão dos grupos por causa do mix."},{"id":"m14-f12","frente":"Ordem lógica do SQL","verso":"FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY."},{"id":"m14-f13","frente":"JOIN perigoso","verso":"Chave não única duplica linhas e infla somas sem erro."},{"id":"m14-f14","frente":"Modelo estrela","verso":"Fato (eventos e números) no centro; dimensões (data, linha, produto) ao redor."},{"id":"m14-f15","frente":"Medida × coluna calculada","verso":"Medida: calcula no contexto dos filtros. Coluna: linha a linha, armazenada."},{"id":"m14-f16","frente":"Erros de visualização","verso":"Eixo cortado em barras, pizza com muitas fatias, 3D, dois eixos Y."},{"id":"m14-f17","frente":"Níveis ISA-95","verso":"0 processo · 1 sensores · 2 CLP/SCADA · 3 MES · 4 ERP."},{"id":"m14-f18","frente":"Rastreabilidade","verso":"Liga insumo → lote → processo → cliente. Reduz o tamanho do recall."},{"id":"m14-f19","frente":"Segurança OT","verso":"Não expor CLP à internet; segregar redes; IEC 62443."},{"id":"m14-f20","frente":"Supervisionado × não supervisionado","verso":"Com rótulo (classificação/regressão) × sem rótulo (agrupamento, anomalias)."},{"id":"m14-f21","frente":"Precisão × recall","verso":"Precisão: dos alarmes, quantos são reais. Recall: dos defeitos, quantos foram pegos."},{"id":"m14-f22","frente":"Paradoxo da acurácia","verso":"Com poucos defeitos, “tudo OK” tem acurácia alta e recall zero."},{"id":"m14-f23","frente":"Vazamento de dados","verso":"Variável que só existe depois do fato; ótimo no teste, falha em produção."},{"id":"m14-f24","frente":"Drift","verso":"O processo muda e o modelo perde desempenho: monitore e retreine."},{"id":"m14-f25","frente":"Escolha do limiar","verso":"Pelo custo esperado dos erros (FN × custo + FP × custo), não pela acurácia."}],"formulas":{"m14-l1":[{"titulo":"Medindo a qualidade","texto":"**Completude = registros preenchidos ÷ registros totais**","nivel":"medio"}],"m14-l2":[{"titulo":"Funções com critérios","texto":"**=SOMASES(Produzidas; Linha; \"L1\"; Turno; \"Noite\")** → 800","nivel":"medio"}],"m14-l3":[{"titulo":"OEE (eficiência global do equipamento)","texto":"**OEE = Disponibilidade × Performance × Qualidade**","nivel":"facil"}],"m14-l7":[{"titulo":"Métricas","texto":"**Acurácia = (VP + VN) ÷ total** = 960 ÷ 1.000 = **96%**","nivel":"medio"}]}},"g-calc1":{"glossario":[["Função","Regra que associa cada entrada a uma única saída."],["Limite","Valor do qual f(x) se aproxima quando x se aproxima de um ponto."],["Continuidade","Ausência de saltos ou buracos: o limite coincide com o valor da função."],["Assíntota","Reta da qual o gráfico se aproxima indefinidamente."],["Derivada","Taxa de variação instantânea; inclinação da tangente."],["Custo marginal","C'(q): custo adicional aproximado de uma unidade a mais."],["Ponto crítico","Ponto onde f'(x) = 0 ou não existe; candidato a máximo ou mínimo."],["Lote econômico (LEC)","Q* = √(2DS/H): minimiza o custo de pedir + estocar."],["Antiderivada","Função F com F' = f."],["Integral definida","Acumulado (área) de f entre a e b."],["Teorema Fundamental do Cálculo","Liga derivada e integral: ∫ₐᵇ f = F(b) − F(a)."],["Ponto de equilíbrio","Quantidade em que receita = custo total."]],"intro":"Cálculo é a matemática da **variação**. Na Engenharia de Produção, a **derivada** mede quanto o custo ou o lucro muda quando se produz uma unidade a mais (custo marginal) e encontra o lote ou a produção ótima; o **limite** mostra para onde tende o custo médio em grande escala; a **integral** soma o que se acumula ao longo do tempo, como produção, consumo de energia e custo total.","formulas":[[["C(q) = CF + cv·q","CF = custo fixo; cv = custo variável por unidade; q = quantidade"],["L(q) = p·q − (CF + cv·q)","p = preço de venda por unidade"],["q* = CF ÷ (p − cv)","ponto de equilíbrio; (p − cv) é a margem de contribuição unitária"],["T(n) = T₁ · n^b, b = log₂(taxa)","tempo da n-ésima unidade; T₁ = tempo da 1ª unidade; taxa = 0,8 para curva de 80%"]],[["lim (q→∞) (CF/q + cv) = cv","o custo médio tende ao custo variável unitário"],["lim (x→a) f(x) = L","f(x) fica tão perto de L quanto se queira para x perto de a"],["f contínua em a ⇔ lim (x→a) f(x) = f(a)","sem saltos nem buracos no ponto a"]],[["f'(x) = lim (h→0) [f(x+h) − f(x)] ÷ h","taxa de variação instantânea"],["(xⁿ)' = n·xⁿ⁻¹","regra da potência"],["CT(Q) = (D/Q)·S + (Q/2)·H","custo anual de pedir + estocar; D = demanda anual, S = custo por pedido, H = custo de manter 1 unidade por ano"],["CT'(Q) = 0 ⇒ Q* = √(2DS ÷ H)","lote econômico (LEC), encontrado pela derivada"]],[["∫ xⁿ dx = xⁿ⁺¹ ÷ (n+1) + C (n ≠ −1)","regra da potência para integrais"],["∫ₐᵇ f(x) dx = F(b) − F(a)","Teorema Fundamental do Cálculo"],["Produção = ∫₀ᵀ r(t) dt","r(t) = taxa de produção; T = duração"],["Energia (kWh) = ∫ P(t) dt","P = potência em kW; a conta de energia é uma integral"]]]},"g-alg1":{"glossario":[["Vetor","Lista ordenada de números."],["Matriz","Tabela retangular de números com m linhas e n colunas."],["Matriz identidade","Matriz quadrada com 1 na diagonal e 0 fora; neutra no produto."],["Transposta","Matriz obtida trocando linhas por colunas."],["Sistema linear","Conjunto de equações lineares; forma Ax = b."],["Escalonamento","Eliminação de Gauss: operações de linha até a forma triangular."],["Determinante","Número que indica, entre outras coisas, se a matriz é invertível."],["Matriz inversa","A⁻¹ tal que A·A⁻¹ = I."],["Modelo de Leontief","Modelo insumo-produto que usa (I − A)⁻¹ para calcular a produção necessária."],["Explosão da BOM","Cálculo das necessidades de componentes a partir do plano de produção."]],"intro":"Álgebra linear organiza muitos números ao mesmo tempo em **vetores e matrizes** e resolve **sistemas de equações**. Na produção, ela calcula o mix de produtos que usa exatamente os recursos disponíveis, explode listas de materiais, organiza dados de várias máquinas e é a base da Pesquisa Operacional (programação linear).","formulas":[[["(AB)ᵢⱼ = Σₖ aᵢₖ · bₖⱼ","produto: linha i de A com coluna j de B"],["A(m×n) · B(n×p) = C(m×p)","condição de existência do produto"],["u · v = u₁v₁ + u₂v₂ + … + uₙvₙ","produto escalar de dois vetores"]],[["A · x = b","A = coeficientes; x = incógnitas; b = termos independentes"],["Lᵢ ← Lᵢ − k·Lⱼ","operação elementar de linha usada no escalonamento"]],[["det [a b; c d] = ad − bc","determinante 2×2"],["x = A⁻¹ · b","solução do sistema quando A é invertível"],["[a b; c d]⁻¹ = (1/(ad − bc)) · [d −b; −c a]","inversa 2×2"]],[["r = B · p","r = necessidades de componentes; B = matriz da BOM; p = plano de produção"],["Necessidade total = (I − N)⁻¹ · d","N = matriz de uso entre itens; d = demanda externa"]]]},"g-desenho":{"glossario":[["Legenda (carimbo)","Quadro com as informações do desenho: título, escala, autor, data."],["Escala","Razão entre a medida no desenho e a medida real."],["Cota","Indicação numérica de uma dimensão real."],["Linha tracejada","Representa arestas ocultas."],["Linha traço-ponto","Representa linhas de centro e eixos de simetria."],["Projeção ortográfica","Representação por vistas perpendiculares a planos."],["1º diedro","Sistema de projeção adotado no Brasil (ABNT)."],["Perspectiva isométrica","Vista 3D com eixos a 120°."],["Hachura","Linhas finas que indicam superfícies cortadas."],["CAD","Desenho assistido por computador."]],"intro":"O desenho é a **linguagem gráfica da engenharia**. O engenheiro de produção lê e faz desenhos de peças, plantas de fábrica (layout), fluxos e dispositivos; precisa entender vistas, escalas e cotas para conversar com projeto, fornecedores e chão de fábrica.","formulas":[[["A(n+1) = A(n) ÷ 2","cada formato da série A tem metade da área do anterior"],["Relação dos lados = √2","permite ampliar/reduzir entre formatos sem distorção"]],[["Medida real = medida no desenho × fator de escala","em 1:100, 1 cm no papel = 100 cm (1 m) reais"],["Medida no desenho = medida real ÷ fator","para desenhar em escala de redução"]],[["Isométrica: eixos a 120°","as três direções têm a mesma redução, por isso as medidas podem ser tomadas diretamente"]],[["Ø","símbolo de diâmetro"],["R","símbolo de raio"]]]},"g-quimica":{"glossario":[["Mol","Quantidade com 6,02 × 10²³ entidades."],["Massa molar","Massa de 1 mol de uma substância (g/mol)."],["Estequiometria","Cálculo das quantidades em reações a partir da equação balanceada."],["Reagente limitante","Reagente que se esgota primeiro e limita o produto."],["Rendimento","Produto real ÷ produto teórico."],["pH","Medida logarítmica da acidez de uma solução."],["Oxidação","Perda de elétrons."],["Redução","Ganho de elétrons."],["Corrosão","Deterioração de metais por reação com o ambiente."],["Ânodo de sacrifício","Metal mais reativo que se corrói no lugar da estrutura protegida."]],"intro":"A química explica do que os materiais são feitos e como reagem. Na produção, ela aparece em **balanços de massa** (quanto de cada insumo), em processos químicos e alimentícios, em **corrosão** e escolha de materiais, em **tratamento de efluentes** e na segurança com produtos perigosos.","formulas":[[["n = m ÷ M","n = quantidade de matéria (mol); m = massa (g); M = massa molar (g/mol)"],["1 mol = 6,02 × 10²³ entidades","constante de Avogadro"]],[["Σ massa dos reagentes = Σ massa dos produtos","Lei de conservação das massas"],["Rendimento (%) = real ÷ teórico × 100","eficiência da reação"],["C = n ÷ V","concentração molar (mol/L)"]],[["C₁ · V₁ = C₂ · V₂","diluição"],["pH = −log[H⁺]","cada unidade de pH = 10 vezes na concentração de H⁺"]],[["Fe → Fe²⁺ + 2e⁻","oxidação do ferro (início da corrosão)"],["m = (M · I · t) ÷ (n · F)","lei de Faraday: massa depositada na eletrólise; F ≈ 96.500 C/mol"]]]},"g-intadm":{"glossario":[["PODC","Planejar, Organizar, Dirigir e Controlar."],["Eficácia","Atingir os objetivos."],["Eficiência","Usar bem os recursos."],["Administração Científica","Escola de Taylor: tempos, métodos e padronização."],["Teoria Clássica","Escola de Fayol: funções e princípios da administração."],["Burocracia","Modelo de Weber baseado em regras formais e impessoalidade."],["Relações Humanas","Escola que destaca fatores sociais e psicológicos (Mayo)."],["Stakeholders","Partes interessadas na organização."],["Missão","Razão de existir da organização."],["Visão","Onde a organização quer chegar."]],"intro":"Administrar é **planejar, organizar, dirigir e controlar** recursos para atingir objetivos. O engenheiro de produção é, na prática, um gestor: coordena pessoas, processos e recursos, e precisa entender as escolas da administração que moldaram as fábricas de hoje.","formulas":[[["Eficácia = resultado alcançado ÷ resultado planejado","fazer a coisa certa (atingir o objetivo)"],["Eficiência = resultado ÷ recursos usados","fazer certo, com pouco desperdício"]],[],[],[]]},"g-intep":{"glossario":[["ABEPRO","Associação Brasileira de Engenharia de Produção."],["Sistema de produção","Conjunto que transforma entradas em saídas de valor."],["Recursos transformados","Materiais, informações ou clientes que são processados."],["Recursos de transformação","Instalações e pessoas que realizam a transformação."],["4 Vs","Volume, variedade, variação e visibilidade."],["Objetivos de desempenho","Qualidade, rapidez, confiabilidade, flexibilidade e custo."],["Produtividade","Saídas ÷ entradas."],["CREA","Conselho Regional de Engenharia e Agronomia."]],"intro":"Apresenta a profissão: o que faz o engenheiro de produção, as **10 áreas da ABEPRO**, a visão da empresa como **sistema de produção** e os indicadores básicos de desempenho. O Módulo 1 do curso aprofunda cada ponto.","formulas":[[],[],[],[["Produtividade = saídas ÷ entradas","ex.: peças por hora-homem"],["Variação (%) = (novo − antigo) ÷ antigo × 100","comparar produtividade entre períodos"]]]},"g-calc2":{"glossario":[["Derivada parcial","Taxa de variação em relação a uma variável, com as outras fixas."],["Gradiente","Vetor das derivadas parciais; aponta para o maior crescimento."],["Curva de nível","Conjunto de pontos com o mesmo valor da função."],["Isoquanta","Combinações de insumos que dão a mesma produção."],["Cobb-Douglas","Função de produção Q = A·K^α·L^β."],["Produto marginal","Aumento da produção por unidade a mais de um insumo."],["Ponto de sela","Ponto crítico que não é máximo nem mínimo."],["Multiplicador de Lagrange","λ: taxa de melhora do ótimo por unidade a mais da restrição."],["Preço-sombra","Valor de uma unidade adicional de um recurso restrito."],["Integral dupla","Soma de uma função sobre uma região do plano."]],"intro":"Na vida real, a produção depende de **várias variáveis ao mesmo tempo**: capital e trabalho, preço de dois produtos, temperatura e tempo. As **derivadas parciais** medem o efeito de cada uma isoladamente; o **gradiente** e os **multiplicadores de Lagrange** encontram o melhor mix respeitando restrições (orçamento, capacidade); as **integrais duplas** somam grandezas espalhadas numa área.","formulas":[[["Q = A · K^α · L^β","Cobb-Douglas; A = tecnologia; α, β = elasticidades do capital e do trabalho"],["α + β > 1 / = 1 / < 1","retornos crescentes / constantes / decrescentes de escala"]],[["∂Q/∂L = β · Q / L","produto marginal do trabalho na Cobb-Douglas"],["∇f = (∂f/∂x, ∂f/∂y)","vetor gradiente"],["Δf ≈ fₓ·Δx + f_y·Δy","diferencial total (aproximação linear)"]],[["∇f = λ · ∇g, g(x, y) = c","condição de Lagrange"],["D = fₓₓ·f_yy − (fₓ_y)²","teste da 2ª derivada"],["K* = (α/(α+β))·B/p_K; L* = (β/(α+β))·B/p_L","Cobb-Douglas com orçamento B e preços p_K, p_L"]],[["∬_R f dA = ∫ₐᵇ ∫_c^d f(x, y) dy dx","integral iterada num retângulo"],["Massa = ∬ ρ(x, y) dA","ρ = densidade superficial"],["dA = r dr dθ","elemento de área em coordenadas polares"]]]},"g-alg2":{"glossario":[["Espaço vetorial","Conjunto com soma e multiplicação por escalar que satisfaz axiomas."],["Linearmente independente","Nenhum vetor é combinação linear dos outros."],["Base","Conjunto LI que gera o espaço."],["Dimensão","Número de vetores de uma base."],["Posto","Número de linhas/colunas LI de uma matriz."],["Transformação linear","Função que preserva soma e multiplicação por escalar."],["Autovalor","λ tal que Av = λv para algum v ≠ 0."],["Autovetor","Vetor não nulo que só é escalado por A."],["Cadeia de Markov","Processo em que a próxima etapa depende só do estado atual."],["Mínimos quadrados","Método que minimiza a soma dos quadrados dos erros."]],"intro":"Aprofunda a álgebra linear: espaços vetoriais, transformações, **autovalores e autovetores** e **mínimos quadrados**. Na produção, isso aparece em **cadeias de Markov** (estado de máquinas, fidelidade de clientes), em **regressão** para previsão de demanda e em técnicas de análise de dados como a **PCA**.","formulas":[[["a₁v₁ + … + aₙvₙ = 0 só com todos aᵢ = 0","definição de vetores LI"],["posto(A) + nulidade(A) = nº de colunas","teorema do posto"]],[["T(x) = A · x","toda transformação linear em ℝⁿ é uma matriz"],["(T₂ ∘ T₁)(x) = A₂ · A₁ · x","composição"]],[["A · v = λ · v","definição de autovalor e autovetor"],["det(A − λI) = 0","equação característica"],["π = π · P, Σπᵢ = 1","distribuição estacionária de Markov"],["π_operando = r ÷ (f + r)","máquina com 2 estados"]],[["AᵀA · x̂ = Aᵀ · b","equações normais (mínimos quadrados)"],["proj_u(v) = (u·v ÷ u·u) · u","projeção de v na direção de u"]]]},"g-comp":{"glossario":[["Algoritmo","Sequência finita de passos para resolver um problema."],["Pseudocódigo","Descrição do algoritmo em linguagem estruturada próxima da natural."],["Variável","Nome associado a um valor armazenado."],["Booleano","Tipo lógico: verdadeiro ou falso."],["Lista","Sequência ordenada de valores acessados por índice."],["Dicionário","Estrutura chave → valor."],["Laço (loop)","Estrutura que repete instruções."],["Função","Bloco reutilizável com parâmetros e retorno."],["Depuração","Processo de encontrar e corrigir erros."],["Referência absoluta","Endereço de célula fixo ao copiar a fórmula ($A$1)."]],"intro":"Programar é dar instruções precisas ao computador. O engenheiro de produção usa lógica de programação para **automatizar planilhas e relatórios**, tratar dados de produção, montar simulações e modelos de otimização (Python, VBA, SQL). O Módulo 14 aprofunda dados e analytics.","formulas":[[["A E B é verdadeiro só se A e B forem verdadeiros","operador lógico E"],["A OU B é falso só se A e B forem falsos","operador lógico OU"]],[["producao = [120, 135, 128]","lista em Python; producao[0] = 120"],["estoque = {\"A10\": 50, \"B20\": 12}","dicionário: estoque[\"A10\"] = 50"]],[["def oee(d, p, q): return d * p * q","função em Python"],["for x in lista: total += x","acumulador num laço"]],[["=PROCV(valor; tabela; coluna; FALSO)","busca exata numa tabela"],["=$B$1*A2","referência absoluta ($) não muda ao copiar a fórmula"]]]},"g-mecbas":{"glossario":[["MRU","Movimento retilíneo uniforme (velocidade constante)."],["MRUV","Movimento com aceleração constante."],["Força resultante","Soma vetorial das forças sobre um corpo."],["Atrito","Força que se opõe ao deslizamento entre superfícies."],["Trabalho","Energia transferida por uma força ao longo de um deslocamento."],["Energia cinética","Energia do movimento: m·v²/2."],["Potência","Trabalho por unidade de tempo."],["Rendimento","Potência útil ÷ potência consumida."],["Impulso","Força × tempo; igual à variação da quantidade de movimento."],["Torque","Tendência de uma força girar um corpo."]],"intro":"Física do movimento e das forças (Física I). Na produção, explica **esteiras e transportadores**, frenagem de **empilhadeiras**, força para empurrar carrinhos (ergonomia), **potência de motores** de elevação e energia gasta em movimentação de materiais.","formulas":[[["x = x₀ + v·t","MRU"],["v = v₀ + a·t","MRUV: velocidade"],["v² = v₀² + 2·a·Δx","Torricelli: sem o tempo"]],[["F = m · a","2ª lei de Newton"],["P = m · g","peso"],["F_at = μ · N","força de atrito"]],[["W = F · d · cos θ","trabalho de uma força"],["Ep = m · g · h","energia potencial gravitacional"],["P = W ÷ t = F · v","potência"],["η = P_útil ÷ P_consumida","rendimento"]],[["p = m · v","quantidade de movimento"],["F · Δt = Δp","teorema do impulso"],["P = τ · ω","potência em rotação (ω em rad/s)"],["v = ω · r","velocidade periférica"]]]},"g-human":{"glossario":[["Divisão do trabalho","Especialização das tarefas entre pessoas ou grupos."],["Alienação","Na leitura marxista, separação do trabalhador em relação ao produto e ao processo de trabalho."],["Racionalização","Organização da vida social por regras, cálculo e eficiência (Weber)."],["Toyotismo","Modelo de organização do trabalho da Toyota: flexibilidade e trabalho em equipe."],["Indústria 4.0","Digitalização e integração da produção (sensores, dados, automação)."],["Ética","Reflexão sobre valores e o que é certo."],["Racismo estrutural","Desigualdades raciais reproduzidas pelas instituições e práticas sociais."],["Acessibilidade","Possibilidade de uso por todas as pessoas, com autonomia e segurança."]],"intro":"Engenharia transforma a sociedade e é transformada por ela. Esta disciplina traz conceitos das ciências sociais para entender o **trabalho**, a **tecnologia**, a **ética**, a **diversidade** e a **cidadania**, que aparecem nas decisões do engenheiro de produção sobre pessoas, processos e comunidade.","formulas":[[],[],[],[]]},"g-metcie":{"glossario":[["Método científico","Procedimento sistemático de formular e testar hipóteses."],["Hipótese","Resposta provisória e testável ao problema."],["Variável dependente","Efeito medido na pesquisa."],["Estudo de caso","Investigação aprofundada de um ou poucos casos no seu contexto."],["Pesquisa-ação","Pesquisa em que o pesquisador participa da mudança que estuda."],["Survey","Levantamento com questionários aplicados a uma amostra."],["Citação direta","Transcrição literal, entre aspas, com página."],["Citação indireta","Paráfrase da ideia do autor, com a fonte."],["Plágio","Uso de obra alheia sem atribuição."],["Revisão por pares","Avaliação de um artigo por especialistas antes da publicação."]],"intro":"Ensina a **pesquisar e escrever** com rigor: formular problemas, escolher métodos, buscar fontes confiáveis, citar e referenciar pelas normas ABNT. É a base do **projeto final (TCC)**, de relatórios técnicos e de qualquer estudo de melhoria baseado em dados.","formulas":[[],[],[["(SOBRENOME, ano, p. X)","citação direta no sistema autor-data"],["Sobrenome (ano)","citação indireta no texto"]],[]]},"g-inteco":{"glossario":[["Demanda","Quantidade desejada pelos compradores a cada preço."],["Oferta","Quantidade que os vendedores desejam vender a cada preço."],["Equilíbrio de mercado","Preço e quantidade em que oferta = demanda."],["Elasticidade-preço","Sensibilidade da quantidade demandada ao preço."],["Custo marginal","Custo de produzir uma unidade adicional."],["Rendimentos decrescentes","Queda do acréscimo de produção por unidade extra de um fator variável."],["Economia de escala","Queda do custo médio com o aumento do volume."],["Oligopólio","Mercado dominado por poucas empresas."],["PIB","Valor dos bens e serviços finais produzidos."],["IPCA","Índice oficial de inflação no Brasil (IBGE)."],["Selic","Taxa básica de juros da economia brasileira."]],"intro":"Economia estuda como pessoas, empresas e países decidem usar recursos escassos. O engenheiro de produção usa **oferta e demanda** para entender preços, **elasticidade** para prever o efeito de promoções, **custos de produção** para decidir volumes e acompanha **juros, inflação e câmbio**, que afetam investimentos e compras.","formulas":[[["Qd = a − b·P","demanda linear"],["Qo = c + d·P","oferta linear"],["Qd = Qo ⇒ P* = (a − c) ÷ (b + d)","preço de equilíbrio"]],[["E = (ΔQ/Q) ÷ (ΔP/P)","elasticidade-preço da demanda"],["Receita = P × Q","o efeito de mudar o preço depende de E"]],[["CT = CF + CV","custo total"],["CMe = CT ÷ Q","custo médio"],["CMg = ΔCT ÷ ΔQ","custo marginal"]],[["Crescimento real ≈ crescimento nominal − inflação","aproximação para taxas pequenas"],["(1 + nominal) = (1 + real) × (1 + inflação)","relação exata (Fisher)"]]]},"g-edo":{"glossario":[["EDO","Equação com uma função de uma variável e suas derivadas."],["Ordem","Maior derivada presente na equação."],["Problema de valor inicial","EDO com condição inicial dada."],["Separável","EDO que pode ser escrita com y de um lado e t do outro."],["Fator integrante","Função que torna integrável uma EDO linear de 1ª ordem."],["Resfriamento de Newton","Taxa de variação da temperatura proporcional à diferença para o ambiente."],["Constante de tempo","τ = 1/k; tempo característico da resposta exponencial."],["Modelo logístico","Crescimento com saturação (curva S)."],["Frequência natural","Frequência em que o sistema oscila livremente."],["Ressonância","Aumento da amplitude quando a excitação tem frequência próxima da natural."],["Confiabilidade","Probabilidade de funcionar sem falhar até um tempo t."]],"intro":"Uma **equação diferencial** relaciona uma grandeza com a sua taxa de variação. Na produção, ela modela o **resfriamento** de produtos num túnel, a **confiabilidade** de equipamentos, a concentração num **tanque de mistura**, a adoção de um **produto novo** e a **vibração** de máquinas.","formulas":[[["dy/dt = k·y ⇒ y(t) = y₀·e^(kt)","crescimento (k > 0) ou decaimento (k < 0)"],["R(t) = e^(−λt)","probabilidade de o equipamento funcionar até t; λ = taxa de falhas"],["MTTF = 1 ÷ λ","tempo médio até a falha (λ constante)"]],[["T(t) = Tₐ + (T₀ − Tₐ)·e^(−kt)","resfriamento de Newton"],["dQ/dt = entrada − saída","balanço de massa num tanque"],["t = (1/k)·ln[(T₀ − Tₐ) ÷ (T − Tₐ)]","tempo para atingir a temperatura T"]],[["dP/dt = r·P·(1 − P/K)","crescimento logístico; K = saturação"],["P(t) = K ÷ (1 + A·e^(−rt))","curva S"]],[["m·x'' + c·x' + k·x = F(t)","sistema massa-mola-amortecedor"],["ωₙ = √(k ÷ m); fₙ = ωₙ ÷ 2π","frequência natural (rad/s e Hz)"],["a·r² + b·r + c = 0","equação característica"]]]},"g-calcvet":{"glossario":[["Curva parametrizada","Curva descrita por r(t)."],["Comprimento de arco","Distância percorrida ao longo da curva."],["Campo vetorial","Associação de um vetor a cada ponto do espaço."],["Gradiente","Vetor que aponta para o maior aumento do campo escalar."],["Divergente","Medida de fonte ou sumidouro de um campo."],["Rotacional","Medida da tendência de rotação de um campo."],["Campo conservativo","Campo gradiente; trabalho independe do caminho."],["Integral de linha","Integral ao longo de uma curva."],["Fluxo","Quanto de um campo atravessa uma superfície."],["Teorema da divergência","Fluxo pela superfície fechada = integral do divergente no volume."]],"intro":"Estende o cálculo a **campos vetoriais**: grandezas com direção em cada ponto, como velocidade de um fluido, forças e fluxo de calor. Na produção, aparece em **escoamento** (vazão em tubulações, ventilação), **trabalho** de forças ao longo de trajetos (robôs, AGVs) e **transferência de calor** — base de Fenômenos de Transporte.","formulas":[[["v(t) = r'(t)","velocidade vetorial"],["L = ∫ₐᵇ |r'(t)| dt","comprimento da trajetória"],["|r'(t)| = √(x'² + y'² + z'²)","rapidez (módulo da velocidade)"]],[["∇·F = ∂P/∂x + ∂Q/∂y + ∂R/∂z","divergente de F = (P, Q, R)"],["q = −k·∇T","lei de Fourier: fluxo de calor contra o gradiente de temperatura"],["∇×F = 0 ⇔ F conservativo (em regiões simples)","teste de campo conservativo"]],[["W = ∫_C F · dr","trabalho ao longo do trajeto"],["W = F · d (F constante, trajeto reto)","produto escalar força × deslocamento"],["∫_C ∇φ · dr = φ(B) − φ(A)","teorema fundamental para integrais de linha"]],[["Φ = ∬_S F · n dS","fluxo através da superfície S"],["∯ F · n dS = ∭ ∇·F dV","teorema da divergência"],["Q = v · A","vazão com velocidade uniforme v perpendicular à área A"]]]},"g-calcnum":{"glossario":[["Erro de arredondamento","Diferença devida à representação finita dos números."],["Erro de truncamento","Diferença por interromper um processo infinito."],["Bissecção","Método de raízes que divide o intervalo ao meio."],["Newton-Raphson","Método de raízes que usa a reta tangente."],["TIR","Taxa que zera o VPL; raiz de uma equação."],["Gauss-Seidel","Método iterativo para sistemas lineares."],["Diagonal dominante","Elemento da diagonal maior que a soma dos outros da linha."],["Interpolação","Estimativa de valores entre pontos conhecidos."],["Regra dos trapézios","Integração numérica por trapézios."],["Método de Euler","Solução numérica de EDO passo a passo."]],"intro":"Muitos problemas não têm solução exata fácil; o **cálculo numérico** encontra aproximações confiáveis com o computador. Na produção: calcular a **TIR** de um investimento (raiz de uma equação), interpolar tabelas, integrar dados medidos (energia, vazão) e simular sistemas passo a passo.","formulas":[[["xₙ₊₁ = xₙ − f(xₙ) ÷ f'(xₙ)","Newton-Raphson"],["n ≥ log₂[(b − a) ÷ ε]","iterações da bissecção para precisão ε"],["Erro relativo = |x − x̄| ÷ |x|","comparar a qualidade de aproximações"]],[["xᵢ⁽ᵏ⁺¹⁾ = (bᵢ − Σⱼ≠ᵢ aᵢⱼxⱼ) ÷ aᵢᵢ","iteração de Jacobi/Gauss-Seidel"],["|aᵢᵢ| > Σⱼ≠ᵢ |aᵢⱼ|","diagonal dominante (garante convergência)"]],[["y = y₀ + (y₁ − y₀)·(x − x₀) ÷ (x₁ − x₀)","interpolação linear"],["min Σ (yᵢ − f(xᵢ))²","critério de mínimos quadrados"]],[["∫ ≈ (h/2)·[y₀ + 2(y₁ + … + yₙ₋₁) + yₙ]","regra dos trapézios"],["yₙ₊₁ = yₙ + h·f(tₙ, yₙ)","método de Euler"]]]},"g-mecger":{"glossario":[["Resultante","Soma vetorial das forças."],["Momento","Tendência de giro: força × braço."],["Binário","Par de forças iguais e opostas que produz rotação pura."],["Diagrama de corpo livre","Desenho do corpo isolado com todas as forças."],["Equilíbrio","Resultante e momento resultante nulos."],["Reação de apoio","Força exercida pelo apoio sobre a estrutura."],["Engaste","Apoio que impede translação e rotação."],["Treliça","Estrutura de barras que trabalham a tração ou compressão."],["Centro de gravidade","Ponto de aplicação do peso total."],["Centro de carga","Distância de referência do CG da carga para a capacidade da empilhadeira."]],"intro":"Estuda **forças em equilíbrio** (estática). O engenheiro de produção usa esses conceitos para entender cargas em **porta-paletes**, **içamento** com cabos e cintas, **estabilidade de empilhadeiras** (centro de gravidade da carga) e reações em vigas e estruturas do layout.","formulas":[[["Fₓ = F·cos θ; F_y = F·sen θ","componentes da força"],["M = F · d","momento; d = braço (perpendicular)"],["R = √(ΣFₓ² + ΣF_y²)","módulo da resultante"]],[["ΣFₓ = 0; ΣF_y = 0","equilíbrio de partícula"],["T = P ÷ (2·sen α)","tração em cada perna de uma lingada simétrica"]],[["ΣM_A = 0 ⇒ R_B = P·a ÷ L","reação no apoio B (carga P a uma distância a de A, vão L)"],["R_A = P − R_B","equilíbrio vertical"],["Carga distribuída: F = q·L no centro","força equivalente"]],[["x̄ = Σ(mᵢ·xᵢ) ÷ Σmᵢ","coordenada do centro de gravidade"],["Capacidade real ≈ capacidade nominal × (c_nominal ÷ c_real)","aproximação pelo equilíbrio de momentos no eixo dianteiro"]]]},"g-eletbas":{"glossario":[["Corrente","Fluxo de carga elétrica (A)."],["Tensão","Diferença de potencial elétrico (V)."],["Resistência","Oposição à passagem de corrente (Ω)."],["Lei de Ohm","V = R·I."],["Potência ativa","Parcela que realiza trabalho (W, kW)."],["Potência reativa","Parcela associada a campos magnéticos e elétricos (var)."],["Fator de potência","P ÷ S; mede o aproveitamento da energia."],["kWh","Unidade de energia: 1 kW durante 1 hora."],["Sistema trifásico","Três tensões senoidais defasadas de 120°."],["NR-10","Norma regulamentadora de segurança em eletricidade."],["LOTO","Bloqueio e etiquetagem de fontes de energia."]],"intro":"A energia elétrica move a fábrica. O engenheiro de produção usa eletricidade para estimar o **consumo e o custo de energia**, entender **fator de potência** e multas na conta, dimensionar cargas e conversar com a manutenção elétrica com segurança (**NR-10**).","formulas":[[["V = R · I","Lei de Ohm"],["P = V · I","potência elétrica"],["R = ρ · L ÷ A","resistência de um condutor"]],[["R_eq(série) = R₁ + R₂ + …","resistência equivalente em série"],["1/R_eq(paralelo) = 1/R₁ + 1/R₂ + …","em paralelo"],["ΣI(nó) = 0; ΣV(malha) = 0","Leis de Kirchhoff"]],[["E (kWh) = P (kW) × t (h)","energia consumida"],["S² = P² + Q²; FP = P ÷ S","triângulo de potências"],["Custo = E × tarifa","custo da energia"]],[["P = √3 · V_L · I_L · FP","potência ativa trifásica"],["V_rms = V_pico ÷ √2","valor eficaz de uma senoide"]]]},"g-estat":{"glossario":[["Média","Soma dos valores ÷ quantidade."],["Mediana","Valor central dos dados ordenados."],["Desvio-padrão","Medida da dispersão em torno da média."],["Coeficiente de variação","Desvio-padrão relativo à média."],["Eventos independentes","A ocorrência de um não altera a probabilidade do outro."],["Distribuição binomial","Nº de sucessos em n tentativas com probabilidade p."],["Distribuição de Poisson","Nº de eventos num intervalo com taxa λ."],["Distribuição normal","Distribuição simétrica em forma de sino."],["Erro-padrão","Desvio-padrão da média amostral: σ/√n."],["Intervalo de confiança","Faixa que contém o parâmetro com a confiança declarada."]],"intro":"Estatística transforma dados em decisão. Na produção, descreve a **variabilidade** dos processos, calcula **probabilidades** de defeito e de falha e estima parâmetros com **amostras**. O Módulo 13 do curso aprofunda os temas com muitos exercícios.","formulas":[[["x̄ = Σxᵢ ÷ n","média"],["s = √[Σ(xᵢ − x̄)² ÷ (n − 1)]","desvio-padrão amostral"],["CV = s ÷ x̄ × 100%","coeficiente de variação"]],[["P(A e B) = P(A)·P(B) (independentes)","regra do produto"],["P(A|B) = P(A e B) ÷ P(B)","probabilidade condicional"],["R_série = R₁ · R₂ · … · Rₙ","confiabilidade de componentes em série"]],[["P(X = k) = C(n,k)·pᵏ·(1 − p)ⁿ⁻ᵏ","binomial"],["P(X = k) = e^(−λ)·λᵏ ÷ k!","Poisson"],["Z = (x − μ) ÷ σ","padronização da normal"]],[["IC = x̄ ± z · σ ÷ √n","intervalo de confiança para a média"],["n = (z · σ ÷ E)²","tamanho de amostra"]]]},"g-engmet":{"glossario":[["ECRS","Eliminar, Combinar, Rearranjar, Simplificar."],["Cronoanálise","Medição de tempos de uma operação padronizada."],["Fator de ritmo","Avaliação da velocidade do operador (100% = normal)."],["Tempo padrão","Tempo normal com tolerâncias."],["Takt time","Tempo disponível ÷ demanda."],["Tempo de ciclo","Ritmo real da linha, dado pelo posto mais lento."],["Balanceamento","Distribuição das tarefas entre postos."],["Gargalo","Recurso que limita a saída do sistema."],["TOC","Teoria das Restrições (Goldratt)."]],"intro":"Como fazer melhor e quanto tempo leva: **estudo de métodos**, **cronoanálise**, **tempo padrão**, **takt time** e **balanceamento de linha**. É a disciplina que mais conversa com o Módulo 4 do curso (em 3 níveis, com muito mais exercícios).","formulas":[[["% que agrega valor = tempo de operação ÷ tempo total × 100","leitura do fluxograma"]],[["TN = TO × FR","tempo normal"],["TP = TN × (1 + T)","tempo padrão (tolerância sobre o TN)"],["n = (z·s ÷ (Er·x̄))²","número de ciclos a medir"]],[["Takt = tempo disponível ÷ demanda","ritmo do cliente"],["N_mín = ⌈Σt ÷ takt⌉","limite inferior de postos"],["Eficiência = Σt ÷ (N × TC)","aproveitamento da linha"]],[["Produção máxima = tempo disponível ÷ TC do gargalo","capacidade da linha"]]]},"g-edp":{"glossario":[["EDP","Equação com derivadas parciais de uma função de várias variáveis."],["Equação do calor","EDP parabólica que descreve difusão de calor."],["Equação da onda","EDP hiperbólica de propagação de ondas."],["Equação de Laplace","EDP elíptica do regime permanente."],["Difusividade térmica","α = k/(ρc): rapidez com que a temperatura se espalha."],["Condição de contorno","O que se impõe nas bordas do domínio."],["Separação de variáveis","Técnica que escreve a solução como produto de funções de uma variável."],["Série de Fourier","Soma de senos e cossenos que representa uma função."],["Diferenças finitas","Aproximação das derivadas por diferenças numa malha."],["Estabilidade numérica","Propriedade de o método não amplificar erros."]],"intro":"Quando uma grandeza varia no **tempo e no espaço** ao mesmo tempo, surge uma EDP. Na produção, ela descreve como o **calor se espalha** numa placa de chocolate, numa peça em tratamento térmico ou na parede de uma câmara fria, como substâncias se **difundem** (secagem, contaminação) e como **ondas** percorrem cabos e estruturas. É a base das simulações por computador.","formulas":[[["∂u/∂t = α · ∂²u/∂x²","equação do calor (1D); α = difusividade térmica"],["∂²u/∂t² = c² · ∂²u/∂x²","equação da onda; c = velocidade de propagação"],["∂²u/∂x² + ∂²u/∂y² = 0","equação de Laplace (regime permanente)"]],[["α = k ÷ (ρ · c)","difusividade térmica (m²/s)"],["t ≈ L² ÷ α","ordem de grandeza do tempo de aquecimento/resfriamento"],["J = −D · ∂C/∂x","lei de Fick (difusão de massa)"]],[["u(x, t) = Σ Bₙ · sen(nπx/L) · e^(−α(nπ/L)²t)","solução do calor numa barra com extremidades a 0"],["f(x) = a₀/2 + Σ [aₙcos(nx) + bₙsen(nx)]","série de Fourier"],["fₙ = n·c ÷ (2L)","frequências naturais de uma corda/cabo de comprimento L"]],[["uᵢⁿ⁺¹ = uᵢⁿ + r·(uᵢ₊₁ⁿ − 2uᵢⁿ + uᵢ₋₁ⁿ)","esquema explícito do calor"],["r = α·Δt ÷ Δx² ≤ 1/2","condição de estabilidade"]]]},"g-destec":{"glossario":[["Corte","Representação imaginária da peça cortada para mostrar o interior."],["Vista auxiliar","Vista que mostra uma face inclinada em verdadeira grandeza."],["Tolerância","Variação permitida de uma dimensão."],["Ajuste com folga","O eixo é sempre menor que o furo."],["Ajuste com interferência","O eixo é sempre maior que o furo."],["Ajuste incerto","Pode haver folga ou interferência."],["GD&T","Dimensionamento e tolerâncias geométricas."],["Datum","Referência para tolerâncias geométricas."],["Rugosidade (Ra)","Medida do acabamento da superfície."],["Lista de peças","Tabela do desenho de conjunto; origem da BOM."]],"intro":"Aprofunda o desenho para **fabricação**: cortes, cotagem funcional, **tolerâncias dimensionais e geométricas**, rugosidade, roscas e **desenho de conjunto com lista de peças**. O engenheiro de produção usa isso para analisar a fabricabilidade, conversar com fornecedores e montar a estrutura de produto (BOM).","formulas":[[],[["Tolerância = Lmáx − Lmín","variação permitida"],["Folga máx = furo máx − eixo mín","no ajuste"],["Folga mín = furo mín − eixo máx","negativa = interferência"]],[["Ra = média dos desvios absolutos do perfil","rugosidade média (µm)"]],[["M d × p","rosca métrica: d = diâmetro nominal (mm); p = passo (mm)"]]]},"g-fister":{"glossario":[["Calor","Energia transferida por diferença de temperatura."],["Dilatação térmica","Variação de dimensões com a temperatura."],["Calor específico","Energia para elevar 1 kg em 1 °C."],["Calor latente","Energia de mudança de fase sem variação de temperatura."],["Condução","Transferência de calor através de um meio sólido."],["Convecção","Transferência de calor por um fluido em movimento."],["Radiação térmica","Transferência por ondas eletromagnéticas."],["1ª lei da termodinâmica","Conservação da energia."],["Ciclo de Carnot","Ciclo ideal de rendimento máximo entre duas temperaturas."],["COP","Coeficiente de desempenho de refrigeradores e bombas de calor."]],"intro":"Calor e energia térmica estão em toda fábrica: **caldeiras**, fornos, câmaras frias, **dilatação** de tubulações e trilhos, **refrigeração** e o custo de energia para aquecer e resfriar. A termodinâmica mostra também os **limites de rendimento** de máquinas térmicas.","formulas":[[["ΔL = α · L₀ · ΔT","dilatação linear; α = coeficiente de dilatação (1/°C)"],["T(K) = T(°C) + 273,15","conversão para Kelvin"]],[["Q = m · c · ΔT","calor sensível"],["Q = m · L","calor latente"],["1 kWh = 3.600 kJ","conversão de energia"]],[["q = k · A · ΔT ÷ L","condução (W)"],["q = h · A · ΔT","convecção (W)"],["q = ε · σ · A · T⁴","radiação; σ = 5,67 × 10⁻⁸ W/(m²·K⁴)"]],[["ΔU = Q − W","1ª lei"],["η_Carnot = 1 − T_f ÷ T_q","rendimento máximo teórico (kelvin)"],["COP = Q_f ÷ W","coeficiente de desempenho de refrigeração"]]]},"g-resmat":{"glossario":[["Tensão normal","Força perpendicular por unidade de área."],["Deformação","Variação relativa de comprimento."],["Módulo de elasticidade","Rigidez do material no regime elástico (E)."],["Escoamento","Início da deformação plástica permanente."],["Coeficiente de segurança","Razão entre resistência e solicitação."],["Cisalhamento","Tensão tangencial ao plano da seção."],["Momento fletor","Esforço interno que flexiona a viga."],["Momento de inércia","Propriedade geométrica que mede a resistência da seção à flexão."],["Flecha","Deslocamento transversal da viga."],["Flambagem","Instabilidade de peças esbeltas comprimidas."]],"intro":"Estuda como peças e estruturas **resistem e se deformam** sob cargas: tensão, deformação, flexão, cisalhamento, torção e flambagem. O engenheiro de produção usa esses conceitos para avaliar **prateleiras, mezaninos, dispositivos e eixos**, entender especificações e coeficientes de segurança e dialogar com a engenharia de projeto.","formulas":[[["σ = F ÷ A","tensão normal"],["ε = ΔL ÷ L₀","deformação"],["σ = E · ε ⇒ ΔL = F·L₀ ÷ (A·E)","Lei de Hooke"]],[["σ_adm = σ_e ÷ CS","tensão admissível"],["τ = V ÷ A","tensão de cisalhamento média"],["CS = σ_e ÷ σ_atuante","coeficiente de segurança da peça"]],[["σ = M · c ÷ I","tensão de flexão; c = distância à linha neutra"],["I = b · h³ ÷ 12","momento de inércia da seção retangular"],["M_máx = P·L ÷ 4","viga bi-apoiada com carga no centro"],["flecha = P·L³ ÷ (48·E·I)","flecha no centro (mesmo caso)"]],[["τ = T · r ÷ J; J = π·d⁴ ÷ 32","torção em eixo maciço"],["P = T · ω","potência transmitida pelo eixo"],["P_cr = π²·E·I ÷ (K·L)²","carga crítica de flambagem (Euler)"]]]},"g-eletron":{"glossario":[["Motor de indução","Motor CA em que o campo girante induz corrente no rotor."],["Rotação síncrona","Velocidade do campo girante: 120f/p."],["Escorregamento","Diferença relativa entre rotação síncrona e real."],["Inversor de frequência","Equipamento que varia a velocidade do motor pela frequência."],["Soft-starter","Dispositivo de partida suave."],["Leis de afinidade","Relações entre rotação, vazão e potência em bombas/ventiladores."],["Diodo","Componente que conduz num só sentido."],["Transistor","Componente que atua como chave ou amplificador."],["Contator","Chave eletromagnética para cargas de potência."],["CLP","Controlador lógico programável."],["Ladder","Linguagem de programação de CLP em forma de diagrama de contatos."]],"intro":"Aplica a eletricidade à fábrica: **motores elétricos**, formas de **partida e acionamento** (incluindo inversores de frequência, que economizam energia), componentes eletrônicos, **sensores** e **CLPs** que automatizam máquinas e linhas.","formulas":[[["n_s = 120 · f ÷ p","rotação síncrona (rpm)"],["s = (n_s − n) ÷ n_s","escorregamento"],["η = P_mecânica ÷ P_elétrica","rendimento do motor"]],[["P₂ ÷ P₁ = (n₂ ÷ n₁)³","lei de afinidade (bombas e ventiladores)"],["Q₂ ÷ Q₁ = n₂ ÷ n₁","vazão proporcional à rotação"]],[["Sinal 4–20 mA: valor = mín + (I − 4) ÷ 16 × (máx − mín)","conversão do sinal padrão de instrumentação"]],[["Ciclo do CLP: ler entradas → executar programa → atualizar saídas","varredura (scan)"]]]},"g-metest":{"glossario":[["Hipótese nula","Afirmação de ausência de efeito ou diferença."],["Erro tipo I","Rejeitar H₀ quando ela é verdadeira (α)."],["Erro tipo II","Não rejeitar H₀ quando ela é falsa (β)."],["p-valor","Probabilidade de um resultado tão extremo se H₀ for verdadeira."],["Teste t pareado","Compara medidas antes e depois nos mesmos itens."],["ANOVA","Análise de variância; compara várias médias."],["Correlação","Medida da relação linear entre duas variáveis."],["R²","Fração da variação explicada pelo modelo."],["DOE","Planejamento de experimentos."],["Interação","Quando o efeito de um fator depende do nível de outro."]],"intro":"Ferramentas para **decidir com dados**: testar se uma melhoria funcionou, comparar máquinas e fornecedores, modelar relações com **regressão** e planejar **experimentos (DOE)** para descobrir quais fatores do processo importam. É a base estatística do Seis Sigma.","formulas":[[["Z = (x̄ − μ₀) ÷ (σ/√n)","teste para a média com σ conhecido"],["t = (x̄ − μ₀) ÷ (s/√n)","teste t com n − 1 graus de liberdade"],["p < α ⇒ rejeita H₀","regra de decisão"]],[["F = QM_entre ÷ QM_dentro","estatística da ANOVA"],["t = d̄ ÷ (s_d/√n)","teste t pareado (d = diferenças)"]],[["b = Σ(x − x̄)(y − ȳ) ÷ Σ(x − x̄)²","inclinação"],["a = ȳ − b·x̄","intercepto"],["R² = 1 − SQ_res ÷ SQ_total","coeficiente de determinação"]],[["Efeito(A) = ȳ(A+) − ȳ(A−)","efeito principal"],["Nº de ensaios = 2ᵏ","fatorial completo com k fatores"]]]},"g-cienamb":{"glossario":[["Ecossistema","Conjunto de seres vivos e meio físico interagindo."],["Ciclo biogeoquímico","Circulação de um elemento entre seres vivos e ambiente."],["Ecologia industrial","Visão da indústria como ecossistema, com troca de materiais e energia."],["DBO","Demanda bioquímica de oxigênio: medida de matéria orgânica na água."],["Eutrofização","Excesso de nutrientes que provoca crescimento de algas e falta de oxigênio."],["CO₂ equivalente","Emissões de gases expressas em CO₂ pelo potencial de aquecimento."],["Escopo 1, 2 e 3","Classificação das emissões: diretas, energia comprada e cadeia de valor."],["Licenciamento ambiental","Processo de autorização de atividades potencialmente poluidoras (LP, LI, LO)."],["Logística reversa","Retorno de produtos e embalagens após o consumo."]],"intro":"Toda produção retira recursos da natureza e devolve resíduos, efluentes e emissões. Esta disciplina dá a base científica — ecossistemas, ciclos, poluição, clima e legislação — para o engenheiro de produção **reduzir impactos**, cumprir a lei e enxergar oportunidades (menos desperdício de água, energia e material).","formulas":[[["Entrada = saída + acúmulo","balanço de massa aplicado a recursos e poluentes"]],[["Carga = concentração × vazão","ex.: kg de DBO por dia lançados"],["Eficiência de remoção = (entrada − saída) ÷ entrada","desempenho de uma estação de tratamento"]],[["Emissão = atividade × fator de emissão","ex.: litros de diesel × kg CO₂ por litro"],["CO₂e = Σ massa do gás × potencial de aquecimento (GWP)","soma ponderada dos gases"]],[]]},"g-ondas":{"glossario":[["MHS","Movimento harmônico simples."],["Período","Tempo de uma oscilação completa."],["Frequência","Número de oscilações por segundo (Hz)."],["Ressonância","Aumento de amplitude quando a excitação coincide com a frequência natural."],["Comprimento de onda","Distância entre dois pontos equivalentes consecutivos da onda."],["Ultrassom","Som acima de 20 kHz, usado em inspeção e medição."],["Decibel","Unidade logarítmica de nível sonoro."],["dB(A)","Nível sonoro com ponderação A, próxima da audição humana."],["Dose de ruído","Soma das frações de exposição em relação aos tempos permitidos."],["Iluminância","Fluxo luminoso por unidade de área (lux)."],["Termografia","Imagem por infravermelho que mostra temperaturas."]],"intro":"Oscilações e ondas aparecem na fábrica como **vibração de máquinas**, **ruído** (que afeta a saúde e é regulado pela NR-15), **ultrassom** para inspeção e medição e **luz** (iluminação dos postos). Esta disciplina dá a base física para entender e medir esses fenômenos.","formulas":[[["x(t) = A · cos(ωt + φ)","MHS"],["f = 1 ÷ T; ω = 2π·f","frequência e frequência angular"],["ω = √(k ÷ m)","sistema massa-mola"]],[["v = λ · f","relação fundamental das ondas"],["d = v · t ÷ 2","distância por eco (ida e volta)"]],[["β = 10 · log(I ÷ I₀)","nível sonoro em dB"],["L_total = 10·log(Σ 10^(Lᵢ/10))","soma de níveis de várias fontes"],["D = Σ (Cᵢ ÷ Tᵢ)","dose de ruído; C = tempo exposto, T = tempo permitido"]],[["c = λ · f","ondas eletromagnéticas no vácuo"],["E = Φ ÷ A","iluminância (lux) = lúmens ÷ m²"]]]},"g-fentran":{"glossario":[["Massa específica","Massa por unidade de volume (ρ)."],["Viscosidade","Resistência de um fluido ao escoamento."],["Pressão manométrica","Pressão medida em relação à atmosférica."],["Vazão","Volume de fluido por unidade de tempo."],["Equação da continuidade","Conservação da massa: v₁A₁ = v₂A₂."],["Bernoulli","Conservação de energia num escoamento ideal."],["Número de Reynolds","Razão entre forças de inércia e viscosas; indica laminar ou turbulento."],["Perda de carga","Energia perdida por atrito no escoamento."],["Altura manométrica","Energia por unidade de peso que a bomba fornece (m)."],["Cavitação","Formação e colapso de bolhas de vapor que danificam bombas."]],"intro":"Estuda o transporte de **quantidade de movimento (fluidos), calor e massa**. Na produção: dimensionar **bombas e tubulações**, reduzir **perdas de carga**, controlar **vazamentos de ar comprimido** (energia cara), ventilação e processos de aquecimento e resfriamento.","formulas":[[["P = P₀ + ρ · g · h","pressão hidrostática"],["1 bar = 100.000 Pa","conversão de unidades"],["Empuxo = ρ_fluido · g · V_imerso","princípio de Arquimedes"]],[["Q = v · A","vazão"],["v₁ · A₁ = v₂ · A₂","continuidade"],["P₁ + ρv₁²/2 + ρgz₁ = P₂ + ρv₂²/2 + ρgz₂","equação de Bernoulli"]],[["Re = ρ · v · D ÷ μ","número de Reynolds"],["h_f = f · (L/D) · v² ÷ (2g)","perda de carga distribuída (Darcy-Weisbach)"],["P = ρ · g · Q · H ÷ η","potência consumida pela bomba"]],[["Q_ar = V_ambiente × trocas/h","vazão de ventilação (m³/h)"],["Energia perdida = potência equivalente do vazamento × horas","custo de vazamentos"],["q = h · A · ΔT","convecção (analogia com transferência de massa)"]]]},"g-ginf":{"glossario":[["Dado","Registro bruto, sem contexto."],["Informação","Dado organizado com contexto e significado."],["Conhecimento tácito","Saber prático difícil de documentar."],["ERP","Sistema integrado de gestão empresarial."],["MES","Sistema de execução da manufatura."],["WMS","Sistema de gestão de armazém."],["Banco de dados relacional","Dados organizados em tabelas relacionadas."],["Chave primária","Campo que identifica unicamente cada registro."],["SQL","Linguagem de consulta a bancos de dados."],["LGPD","Lei Geral de Proteção de Dados Pessoais (Lei 13.709/2018)."],["Tríade CID","Confidencialidade, integridade e disponibilidade."]],"intro":"Decisões boas precisam de **informação certa, no tempo certo**. A disciplina trata de dados e informação, **sistemas de informação** (ERP, MES, WMS, BI), **bancos de dados**, qualidade de dados, **LGPD** e segurança da informação. O Módulo 14 aprofunda a parte de dados e analytics.","formulas":[[],[],[["SELECT maquina, SUM(qtd) FROM producao GROUP BY maquina","produção total por máquina"],["… JOIN produtos ON producao.cod = produtos.cod","cruzar tabelas pela chave"]],[["Acuracidade (%) = registros corretos ÷ registros verificados × 100","indicador de qualidade de dados"]]]},"g-tecmat":{"glossario":[["Ductilidade","Capacidade de deformar plasticamente antes de romper."],["Tenacidade","Capacidade de absorver energia até a fratura."],["Dureza","Resistência à penetração ou ao risco."],["Fadiga","Falha sob cargas cíclicas abaixo do escoamento."],["Aço inoxidável","Aço com cromo suficiente para resistir à corrosão."],["Têmpera","Resfriamento rápido que endurece o aço."],["Revenimento","Reaquecimento após a têmpera para reduzir a fragilidade."],["Recozimento","Tratamento que amolece e alivia tensões."],["Termoplástico","Polímero que amolece com o calor e pode ser remoldado."],["Termofixo","Polímero que cura irreversivelmente."],["Compósito","Material formado por dois ou mais constituintes."]],"intro":"Conhecer os materiais — metais, polímeros, cerâmicos e compósitos — permite **escolher o material certo** para produtos, embalagens, ferramentas e instalações, entender **ensaios** e **tratamentos térmicos** e prever o comportamento em serviço. É a base de Processos de Fabricação.","formulas":[[["Resistência específica = σ ÷ ρ","resistência por unidade de massa (importante em transporte)"]],[["Alongamento (%) = (L_f − L₀) ÷ L₀ × 100","ductilidade no ensaio de tração"]],[],[["Custo por desempenho = custo ÷ propriedade requerida","comparação simples entre candidatos"]]]},"g-estqual":{"glossario":[["Causa comum","Variação natural e inerente ao processo."],["Causa especial","Variação por evento identificável e corrigível."],["Carta de controle","Gráfico com limites para monitorar a estabilidade do processo."],["Limites de controle","Faixa natural do processo (normalmente ±3σ)."],["Limites de especificação","Faixa exigida pelo cliente ou projeto."],["Cp","Capacidade potencial do processo."],["Cpk","Capacidade considerando a centralização."],["NQA (AQL)","Nível de qualidade aceitável num plano de amostragem."],["Curva CO","Probabilidade de aceitar o lote × qualidade do lote."],["MTBF","Tempo médio entre falhas."],["MTTR","Tempo médio para reparo."],["Curva da banheira","Taxa de falhas ao longo da vida do equipamento."]],"intro":"Aplica a estatística ao controle da qualidade e da confiabilidade: **controle estatístico de processo (CEP)**, **capacidade de processo (Cp, Cpk)**, **amostragem de aceitação** e **confiabilidade** de equipamentos (MTBF, MTTR, disponibilidade). É o coração da Engenharia da Qualidade e da Manutenção.","formulas":[[["LSC = X̿ + A₂·R̄; LIC = X̿ − A₂·R̄","carta X̄ (A₂ = 0,577 para n = 5)"],["LSC_R = D₄·R̄; LIC_R = D₃·R̄","carta R (n = 5: D₄ = 2,114; D₃ = 0)"],["p̄ ± 3·√(p̄(1 − p̄)/n)","limites da carta p"]],[["Cp = (LSE − LIE) ÷ (6σ)","capacidade potencial"],["Cpk = mín[(LSE − μ)/(3σ); (μ − LIE)/(3σ)]","capacidade real"]],[["P_aceitar = Σ (k = 0 até c) C(n,k)·pᵏ·(1 − p)ⁿ⁻ᵏ","probabilidade de aceitação (binomial)"]],[["A = MTBF ÷ (MTBF + MTTR)","disponibilidade"],["R_série = Π Rᵢ","todos precisam funcionar"],["R_paralelo = 1 − Π(1 − Rᵢ)","basta um funcionar"],["R(t) = e^(−(t/η)^β)","Weibull"]]]},"g-segtrab":{"glossario":[["Perigo","Fonte com potencial de causar dano."],["Risco","Combinação de probabilidade e severidade de um dano."],["Incidente","Evento que poderia ter causado dano (quase acidente)."],["Pirâmide de Bird","Relação entre incidentes, acidentes leves e graves."],["Hierarquia de controles","Eliminação, substituição, engenharia, administrativos e EPI."],["EPI","Equipamento de proteção individual (NR-6)."],["EPC","Equipamento de proteção coletiva."],["PGR","Programa de Gerenciamento de Riscos (NR-1)."],["CIPA","Comissão Interna de Prevenção de Acidentes e de Assédio (NR-5)."],["APR","Análise preliminar de riscos."],["CAT","Comunicação de acidente de trabalho."],["Taxa de frequência","Acidentes por milhão de horas-homem trabalhadas."]],"intro":"Segurança não é custo nem burocracia: é condição para produzir. O engenheiro de produção identifica **perigos e riscos**, aplica a **hierarquia de controles**, conhece as principais **Normas Regulamentadoras (NRs)**, investiga acidentes e acompanha **indicadores** de segurança.","formulas":[[["Risco = probabilidade × severidade","matriz de risco"],["TF = nº de acidentes × 1.000.000 ÷ HHT","taxa de frequência (ABNT NBR 14280); HHT = horas-homem trabalhadas"],["TG = dias perdidos (+ debitados) × 1.000.000 ÷ HHT","taxa de gravidade"]],[],[],[["Prioridade = P × S (ex.: escalas de 1 a 5)","pontuação na matriz de risco"]]]},"g-procfab":{"glossario":[["Fundição","Obtenção de peças vazando metal líquido em moldes."],["Forjamento","Conformação por impacto ou pressão."],["Estampagem","Corte e conformação de chapas em prensas."],["Extrusão","Passagem forçada do material por uma matriz."],["Usinagem","Remoção de material em forma de cavaco."],["Velocidade de corte","Velocidade relativa entre ferramenta e peça (m/min)."],["Avanço","Deslocamento da ferramenta por rotação (mm/rot)."],["CNC","Comando numérico computadorizado."],["MIG/MAG","Soldagem com arame contínuo e gás de proteção."],["TIG","Soldagem com eletrodo de tungstênio não consumível."],["Injeção plástica","Moldagem de plástico fundido injetado sob pressão."],["Manufatura aditiva","Fabricação camada por camada (impressão 3D)."]],"intro":"Como as peças são feitas: **fundição, conformação, usinagem, soldagem**, processos de **plásticos** e **manufatura aditiva**. O engenheiro de produção escolhe o processo pelo **volume, custo, tolerância e prazo**, calcula tempos de fabricação e planeja a produção considerando setups e ferramental.","formulas":[[["q* = (CF₂ − CF₁) ÷ (cv₁ − cv₂)","volume de indiferença entre dois processos (custo fixo × variável)"]],[["n = 1.000 · vc ÷ (π · D)","rotação (rpm); vc em m/min, D em mm"],["t_c = L ÷ (f · n)","tempo de corte (min); L = comprimento (mm), f = avanço (mm/rot)"]],[["Produtividade = massa depositada por hora × fator de operação","comparação entre processos de soldagem"]],[["Custo unitário = CF ÷ q + cv","o ferramental se dilui no volume"],["Produção/h = 3.600 ÷ ciclo (s) × cavidades","injeção/termoformagem"]]]},"g-contab":{"glossario":[["Ativo","Bens e direitos da empresa."],["Passivo","Obrigações com terceiros."],["Patrimônio líquido","Recursos dos sócios: ativo − passivo."],["DRE","Demonstração do resultado do período."],["CPV","Custo dos produtos vendidos."],["Regime de competência","Registro de receitas e despesas quando ocorrem."],["Liquidez corrente","Ativo circulante ÷ passivo circulante."],["Giro do estoque","CPV ÷ estoque médio."],["Margem de contribuição","Preço menos custos e despesas variáveis."],["Ponto de equilíbrio","Volume em que o lucro é zero."],["Custo afundado","Custo já incorrido que não muda com a decisão."],["Custo evitável","Custo que deixa de existir se a atividade for eliminada."]],"intro":"A contabilidade gerencial traduz a operação em **números para decidir**: ler **balanço e DRE**, calcular **margem de contribuição e ponto de equilíbrio**, analisar índices e montar **orçamentos**. O engenheiro de produção usa isso para justificar melhorias, escolher o mix e decidir entre fazer ou comprar.","formulas":[[["Ativo = Passivo + Patrimônio Líquido","equação fundamental"],["Lucro bruto = Receita líquida − CPV","CPV = custo dos produtos vendidos"],["Lucro operacional = Lucro bruto − despesas operacionais","antes de juros e impostos sobre o lucro"]],[["Liquidez corrente = AC ÷ PC","curto prazo"],["Giro = CPV ÷ estoque médio","vezes por ano"],["Cobertura (dias) = 365 ÷ giro","quantos dias de consumo o estoque cobre"],["ROI = lucro ÷ investimento","retorno"]],[["MCu = p − cv","margem de contribuição unitária"],["PE = CF ÷ MCu","ponto de equilíbrio (unidades)"],["MC por hora do gargalo = MCu ÷ horas do gargalo por unidade","priorização com recurso restrito"]],[["Variação = realizado − orçado","análise orçamentária"],["Decisão incremental = receitas incrementais − custos incrementais","só o que muda com a decisão"]]]},"g-po1":{"glossario":[["Pesquisa Operacional","Uso de modelos matemáticos para apoiar decisões."],["Variável de decisão","Quantidade a ser escolhida pelo modelo."],["Função objetivo","Expressão a maximizar ou minimizar."],["Restrição","Limite que a solução deve respeitar."],["Região viável","Conjunto de soluções que atendem a todas as restrições."],["Simplex","Algoritmo que percorre os vértices até o ótimo."],["Preço-sombra","Melhora do objetivo por unidade adicional de um recurso."],["Folga","Parte do recurso não usada na solução."],["Custo reduzido","Quanto o coeficiente de uma variável fora da base precisa melhorar para ela entrar."],["Problema de transporte","Minimizar o custo de enviar de origens a destinos."],["Método húngaro","Algoritmo para o problema de designação."]],"intro":"A Pesquisa Operacional usa **modelos matemáticos para encontrar a melhor decisão** com recursos limitados. Com **programação linear**, o engenheiro de produção define o **mix de produção** que maximiza o lucro, a **mistura** de menor custo, o plano de **transporte** mais barato e a **designação** de pessoas a tarefas.","formulas":[[["máx Z = c₁x₁ + c₂x₂ + … + cₙxₙ","função objetivo"],["a₁₁x₁ + … + a₁ₙxₙ ≤ b₁","restrição de recurso"],["xᵢ ≥ 0","não negatividade"]],[["Ótimo em um vértice da região viável","teorema fundamental da PL"],["Folga = recurso disponível − recurso usado","recurso que sobra no ótimo"]],[["Preço-sombra = ΔZ ÷ Δbᵢ","valor de uma unidade adicional do recurso i"]],[["mín Σᵢ Σⱼ cᵢⱼ·xᵢⱼ","custo total de transporte"],["Σⱼ xᵢⱼ ≤ oferta_i; Σᵢ xᵢⱼ ≥ demanda_j","restrições de oferta e demanda"]]]},"g-ergo":{"glossario":[["Ergonomia","Estudo das interações entre pessoas e sistemas para bem-estar e desempenho."],["Trabalho prescrito","O que o procedimento determina."],["Trabalho real","O que a pessoa efetivamente faz para cumprir a tarefa."],["Antropometria","Medidas do corpo humano."],["Percentil","Valor abaixo do qual está uma porcentagem da população."],["NIOSH","Equação para o limite de peso recomendado em levantamentos."],["Índice de levantamento","Peso da carga ÷ limite recomendado."],["RULA","Método de avaliação rápida de postura de membros superiores."],["LER/DORT","Lesões por esforços repetitivos / distúrbios osteomusculares relacionados ao trabalho."],["AET","Análise Ergonômica do Trabalho."],["Carga mental","Demanda cognitiva do trabalho."]],"intro":"Ergonomia adapta o trabalho às pessoas — e não o contrário — para unir **saúde, segurança, conforto e desempenho**. O engenheiro de produção projeta postos, métodos e a organização do trabalho considerando **antropometria, biomecânica, carga mental e turnos**, cumprindo a **NR-17**.","formulas":[[],[["Pₖ = μ + z·σ","percentil (z = −1,645 para P5; +1,645 para P95)"]],[["LPR = 23 · HM · VM · DM · AM · FM · CM","NIOSH; HM = 25/H (H em cm, distância horizontal)"],["IL = peso da carga ÷ LPR","índice de levantamento"]],[]]},"g-gqual":{"glossario":[["TQM","Gestão da qualidade total."],["PDCA","Planejar, Fazer, Checar, Agir."],["Diagrama de Pareto","Gráfico que ordena causas pela frequência."],["Diagrama de Ishikawa","Diagrama de causa e efeito (espinha de peixe)."],["6M","Método, máquina, material, mão de obra, meio ambiente e medida."],["ISO 9001","Norma de requisitos de sistema de gestão da qualidade."],["Não conformidade","Não atendimento de um requisito."],["Ação corretiva","Ação para eliminar a causa de uma não conformidade."],["Custos da qualidade","Prevenção, avaliação e falhas internas e externas."],["DMAIC","Definir, Medir, Analisar, Melhorar, Controlar."],["DPMO","Defeitos por milhão de oportunidades."]],"intro":"Qualidade é atender e superar o que o cliente precisa, de forma consistente e ao menor custo. A disciplina apresenta os **gurus** e a evolução da qualidade, as **7 ferramentas**, o **PDCA**, a **ISO 9001**, os **custos da qualidade** e uma introdução ao **Seis Sigma**.","formulas":[[],[["% acumulado do Pareto = Σ ocorrências das categorias ÷ total","mostra onde concentrar esforços"]],[],[["DPMO = defeitos ÷ (unidades × oportunidades) × 1.000.000","defeitos por milhão de oportunidades"],["CQ = prevenção + avaliação + falhas internas + falhas externas","custo total da qualidade"]]]},"g-confest":{"glossario":[["Solicitação","Efeito das cargas sobre a estrutura (S)."],["Resistência","Capacidade da estrutura de suportar solicitações (R)."],["Valor característico","Valor com probabilidade definida de ser ultrapassado."],["Margem de segurança","M = R − S."],["Probabilidade de falha","P(M < 0)."],["Índice de confiabilidade","β = μ_M/σ_M; mede a distância até a falha em desvios-padrão."],["Coeficiente parcial","Fator que majora cargas ou minora resistências nas normas."],["Estado-limite último","Estado de ruptura ou perda de equilíbrio."],["Estado-limite de serviço","Estado que compromete o uso (deformação, vibração)."],["Risco","Probabilidade × consequência."]],"intro":"Cargas e resistências não são números exatos: variam. A confiabilidade estrutural trata essas **incertezas com probabilidade** para calcular a **probabilidade de falha** e o **índice de confiabilidade β**, e explica a lógica dos **coeficientes de segurança** das normas. O engenheiro de produção usa isso em decisões de **risco** sobre estruturas, equipamentos e cargas.","formulas":[[["CV = σ ÷ μ","variabilidade relativa"],["f_k = μ − 1,645·σ","valor característico (quantil de 5%, distribuição normal)"]],[["M = R − S","margem de segurança"],["β = (μ_R − μ_S) ÷ √(σ_R² + σ_S²)","índice de confiabilidade (normais independentes)"],["P_f = Φ(−β)","probabilidade de falha"]],[["CS = μ_R ÷ μ_S","coeficiente de segurança central"],["γ_f · S_k ≤ R_k ÷ γ_m","verificação semiprobabilística (coeficientes parciais)"]],[["Risco = P_f × custo da consequência","valor esperado da perda"],["R_série = Π R_i","sistema sem redundância"]]]},"g-psico":{"glossario":[["Hierarquia de Maslow","Necessidades humanas em níveis, das fisiológicas à autorrealização."],["Fatores higiênicos","Condições que evitam insatisfação (Herzberg)."],["Fatores motivadores","Aspectos que geram satisfação e motivação (Herzberg)."],["Teoria da expectância","Motivação depende de expectativa, instrumentalidade e valência (Vroom)."],["Equipe","Grupo com objetivo comum e interdependência."],["Liderança situacional","Estilo que se adapta à maturidade da equipe."],["Segurança psicológica","Confiança de que se pode falar sem punição."],["Cultura organizacional","Valores e pressupostos compartilhados."],["Abordagem sociotécnica","Otimização conjunta dos sistemas técnico e social."],["Burnout","Síndrome de esgotamento ligada ao trabalho (CID-11)."],["Riscos psicossociais","Fatores da organização do trabalho que afetam a saúde mental."]],"intro":"Processos são feitos por **pessoas**. Entender **motivação, grupos, liderança, cultura e saúde mental** ajuda o engenheiro de produção a implantar mudanças com adesão, formar equipes eficazes e prevenir adoecimento — condições para que as melhorias se sustentem.","formulas":[[["Motivação (Vroom) ∝ expectativa × instrumentalidade × valência","se um termo for zero, a motivação cai"]],[],[],[]]},"g-planinst":{"glossario":[["Centro de gravidade","Localização que minimiza aproximadamente o transporte ponderado."],["Ponderação de fatores","Comparação de alternativas por notas e pesos."],["Layout posicional","Produto parado, recursos se deslocam."],["Layout funcional","Recursos agrupados por função."],["Layout celular","Células dedicadas a famílias de produtos."],["Layout por produto","Recursos em linha na sequência das operações."],["SLP","Planejamento sistemático do layout (Muther)."],["Carta de relações","Matriz AEIOUX de proximidade desejada entre setores."],["Carga-distância","Soma de fluxo × distância; mede o esforço de movimentação."],["Guerchet","Método de estimativa de áreas de postos."]],"intro":"Onde construir a fábrica, como arranjar máquinas e pessoas e quanto espaço e equipamento são necessários. O **layout** define distâncias, fluxos, estoques e segurança por muitos anos — é uma das decisões de maior impacto do engenheiro de produção.","formulas":[[["x̄ = Σ(xᵢ·wᵢ) ÷ Σwᵢ; ȳ = Σ(yᵢ·wᵢ) ÷ Σwᵢ","centro de gravidade (w = volume movimentado)"],["Pontuação = Σ (peso × nota)","ponderação de fatores"]],[],[["Custo de movimentação = Σ (fluxoᵢⱼ × distânciaᵢⱼ × custo unitário)","comparação de layouts"],["Distância retangular = |x₁ − x₂| + |y₁ − y₂|","trajeto em corredores ortogonais"]],[["N = (D × tp) ÷ (T_disp × η)","número de máquinas; D = demanda, tp = tempo por unidade"],["Posições-palete = estoque médio ÷ caixas por palete","dimensionamento de armazém"]]]},"g-projorg":{"glossario":[["Amplitude de controle","Número de subordinados diretos de um gestor."],["Unidade de comando","Cada pessoa tem um único chefe."],["Centralização","Concentração das decisões no topo."],["Formalização","Grau de padronização por regras escritas."],["Estrutura funcional","Departamentalização por funções."],["Estrutura matricial","Dupla subordinação: função e projeto."],["Tecnoestrutura","Analistas que padronizam o trabalho (Mintzberg)."],["Enriquecimento de cargo","Aumento da autonomia e responsabilidade."],["Gestão por processos","Gestão ponta a ponta dos fluxos de trabalho."],["RACI","Matriz de papéis: responsável, aprovador, consultado, informado."]],"intro":"Como organizar pessoas, cargos e áreas para que a estratégia aconteça: **estruturas organizacionais**, **departamentalização**, **amplitude de controle**, **desenho de cargos** e **gestão por processos**. O engenheiro de produção participa de reorganizações e define papéis e responsabilidades.","formulas":[[["Nº de gestores ≈ nº de pessoas ÷ amplitude (por nível)","estimativa de níveis hierárquicos"]],[],[],[]]},"g-po2":{"glossario":[["Programação inteira","PL com variáveis restritas a valores inteiros."],["Variável binária","Variável que vale 0 ou 1."],["Branch-and-bound","Método de busca para programação inteira."],["Caminho mínimo","Rota de menor custo entre dois nós de uma rede."],["Utilização","ρ = λ/μ: fração do tempo em que o servidor está ocupado."],["M/M/1","Fila com chegadas e atendimentos exponenciais e um servidor."],["Lei de Little","L = λ·W."],["Monte Carlo","Simulação por sorteios repetidos."],["Eventos discretos","Simulação em que o estado muda em instantes específicos."],["VME","Valor monetário esperado."],["Maximin","Critério pessimista: escolhe a alternativa com o melhor pior caso."]],"intro":"Amplia a caixa de ferramentas da PO: **programação inteira** (decisões sim/não), **redes**, **teoria das filas** (dimensionar atendimentos e recursos), **simulação** (sistemas com incerteza) e **teoria da decisão** (escolher sob risco).","formulas":[[["y ∈ {0, 1}","variável binária (decisão sim/não)"],["x ≤ M · y","só produz (x > 0) se a instalação/setup existir (y = 1)"],["máx Σ vᵢyᵢ s.a. Σ cᵢyᵢ ≤ orçamento","seleção de projetos (mochila)"]],[["ρ = λ ÷ μ","utilização"],["W = 1 ÷ (μ − λ)","tempo médio no sistema (M/M/1)"],["Wq = ρ ÷ (μ − λ)","tempo médio na fila (M/M/1)"],["L = λ · W","lei de Little"]],[["x = F⁻¹(u), u ~ Uniforme(0,1)","geração de valores aleatórios por transformação inversa"],["x = −ln(u) ÷ λ","sorteio de tempo exponencial"]],[["VME = Σ pᵢ · resultadoᵢ","valor monetário esperado"],["VEIP = VE com informação perfeita − melhor VME","valor da informação perfeita"]]]},"g-gamb":{"glossario":[["SGA","Sistema de gestão ambiental."],["ISO 14001","Norma de requisitos para SGA."],["Aspecto ambiental","Elemento da atividade que interage com o meio ambiente."],["Impacto ambiental","Mudança no ambiente resultante dos aspectos."],["Produção mais limpa","Prevenção da poluição na fonte."],["ACV","Avaliação do ciclo de vida (ISO 14040/14044)."],["Ecodesign","Projeto de produto considerando o ciclo de vida."],["Economia circular","Manter produtos e materiais em uso pelo maior tempo possível."],["Ecoeficiência","Desempenho ambiental por unidade produzida."],["Resíduo Classe I","Resíduo perigoso (NBR 10004)."],["PGRS","Plano de gerenciamento de resíduos sólidos."]],"intro":"Transforma a preocupação ambiental em **gestão**: sistema de gestão ambiental (**ISO 14001**), **aspectos e impactos**, **produção mais limpa**, **avaliação do ciclo de vida**, gestão de **resíduos** e **economia circular**. Reduzir desperdício de material, água e energia é bom para o ambiente e para o custo.","formulas":[[],[["Significância = severidade × frequência (× peso legal)","critério comum de priorização"]],[["Ecoeficiência = consumo (ou emissão) ÷ produção","ex.: m³ de água por tonelada"],["Redução (%) = (antes − depois) ÷ antes × 100","acompanhamento de metas"]],[["Taxa de reciclagem = resíduo reciclado ÷ resíduo gerado × 100","indicador de desempenho"]]]},"g-engeco":{"glossario":[["Juros compostos","Juros calculados sobre o montante acumulado."],["Valor presente","Valor de hoje de um fluxo futuro descontado."],["Taxa equivalente","Taxa de outro período que produz o mesmo montante."],["Série uniforme","Sequência de pagamentos iguais e periódicos."],["Tabela Price","Sistema de prestações iguais."],["SAC","Sistema de amortização constante."],["TMA","Taxa mínima de atratividade."],["VPL","Valor presente líquido."],["TIR","Taxa interna de retorno: zera o VPL."],["Payback","Tempo de recuperação do investimento."],["Depreciação","Perda de valor contábil de um ativo ao longo da vida útil."],["CAE","Custo anual equivalente."]],"intro":"Toda melhoria, máquina ou projeto precisa se pagar. A engenharia econômica leva em conta o **valor do dinheiro no tempo** para comparar alternativas: **juros compostos, séries, VPL, TIR, payback**, depreciação, impostos e substituição de equipamentos.","formulas":[[["F = P · (1 + i)ⁿ","valor futuro"],["P = F ÷ (1 + i)ⁿ","valor presente"],["i_anual = (1 + i_mensal)¹² − 1","taxa equivalente"]],[["P = A · [(1 + i)ⁿ − 1] ÷ [i · (1 + i)ⁿ]","valor presente de uma série uniforme"],["A = P · [i · (1 + i)ⁿ] ÷ [(1 + i)ⁿ − 1]","prestação (Price)"]],[["VPL = −I₀ + Σ FCₜ ÷ (1 + TMA)ᵗ","valor presente líquido"],["VPL(TIR) = 0","definição da TIR"],["Payback simples = I₀ ÷ FC anual (fluxos iguais)","tempo de retorno"]],[["Depreciação linear = (C − VR) ÷ n","C = custo; VR = valor residual; n = vida útil"],["CAE = VPL × [i(1 + i)ⁿ] ÷ [(1 + i)ⁿ − 1]","custo anual equivalente"],["Benefício fiscal = depreciação × alíquota do IR","economia de imposto"]]]},"g-custos":{"glossario":[["Custo","Gasto relativo à produção de bens ou serviços."],["Despesa","Gasto para vender e administrar."],["Custo direto","Custo identificado diretamente com o produto."],["Custo indireto","Custo que precisa de rateio."],["CIF","Custos indiretos de fabricação."],["MOD","Mão de obra direta."],["Custeio por absorção","Método em que todos os custos de produção vão para os produtos."],["Custeio variável","Método em que só custos variáveis vão para os produtos."],["ABC","Custeio baseado em atividades."],["Direcionador de custo","Medida que explica o consumo de uma atividade."],["Custo-padrão","Custo que o produto deveria ter em condições eficientes."],["Markup","Índice aplicado ao custo para formar o preço."]],"intro":"Quanto custa, de verdade, cada produto? A disciplina apresenta a **classificação de custos**, os métodos de **custeio por absorção, variável e ABC**, o **custo-padrão** com análise de variações e a **formação de preço**. É indispensável para decidir mix, preço, terceirização e melhorias.","formulas":[[["Custo de produção = MP + MOD + CIF","componentes do custo"],["Custo unitário = custo total ÷ quantidade","com o volume, o fixo unitário cai"]],[["Taxa de rateio = CIF total ÷ base total","ex.: R$ por hora-máquina"],["CIF do produto = taxa × base consumida pelo produto","alocação"]],[["Custo da atividade ÷ volume do direcionador = taxa do direcionador","ex.: R$ por setup"],["Custo ABC do produto = Σ taxa × consumo do direcionador","alocação por atividades"]],[["Var. preço = (Pr − Pp) × Qr","variação de preço"],["Var. quantidade = (Qr − Qp) × Pp","variação de eficiência"],["Preço = custo ÷ (1 − Σ%)","formação de preço por markup divisor"]]]},"g-gmanut":{"glossario":[["Manutenção corretiva","Intervenção após a falha."],["Manutenção preventiva","Intervenção em intervalos definidos."],["Manutenção preditiva","Intervenção baseada no monitoramento da condição."],["Manutenção detectiva","Busca de falhas ocultas em sistemas de proteção."],["MTBF","Tempo médio entre falhas."],["MTTR","Tempo médio para reparo."],["Backlog","Serviços pendentes em relação à capacidade da equipe."],["TPM","Manutenção produtiva total."],["Manutenção autônoma","Cuidados básicos feitos pelo operador."],["RCM","Manutenção centrada em confiabilidade."],["FMEA","Análise de modos de falha e efeitos."],["NPR","Número de prioridade de risco: S × O × D."]],"intro":"Máquina parada é produção perdida. A gestão da manutenção escolhe a **estratégia certa** para cada equipamento (corretiva, preventiva, preditiva), usa **indicadores** (MTBF, MTTR, disponibilidade, backlog), aplica **TPM** e **RCM/FMEA** e organiza o **planejamento e controle da manutenção (PCM)**.","formulas":[[],[["MTBF = tempo de operação ÷ nº de falhas","confiabilidade"],["MTTR = tempo de reparo ÷ nº de reparos","manutenibilidade"],["A = MTBF ÷ (MTBF + MTTR)","disponibilidade"],["Backlog = horas pendentes ÷ horas disponíveis da equipe por dia","carga acumulada (dias)"]],[["NPR = S × O × D","número de prioridade de risco (FMEA)"],["OEE = D × P × Q","indicador central do TPM"]],[["Custo total = custo de manutenção + custo da produção perdida","equilíbrio entre prevenir e corrigir"],["% preventiva = horas preventivas ÷ horas totais × 100","indicador de maturidade"]]]},"g-pcp1":{"glossario":[["Suavização exponencial","Previsão que corrige uma fração α do erro."],["MAD","Desvio absoluto médio."],["Sinal de rastreamento","Σ erros ÷ MAD; detecta viés."],["Planejamento agregado","Plano por família e por mês."],["S&OP","Planejamento integrado de vendas e operações."],["PMP","Plano mestre de produção."],["ATP","Quantidade disponível para promessa."],["BOM","Lista de materiais."],["Necessidade líquida","Necessidade bruta menos estoque e recebimentos programados."],["Lead time","Tempo entre liberar a ordem e receber o item."],["Média móvel ponderada","Previsão com pesos que somam 1, maiores nos dados recentes."],["Método de Holt","Amortecimento exponencial com ajuste de tendência (nível S e tendência T)."],["DAM","Desvio absoluto médio das previsões."],["EQM","Erro quadrático médio; pune mais os erros grandes."],["Solver","Suplemento do Excel usado para achar os parâmetros que minimizam o erro."],["Demanda dependente","Demanda de componentes, calculada a partir do plano do produto final."],["ERP","Sistema integrado e modular de gestão de toda a empresa."],["Revisão periódica","Política que revisa o estoque a intervalos fixos e pede até o nível máximo."],["Mín–máx","Ao atingir o mínimo, repõe até o máximo."],["Posição de estoque","Físico + em trânsito − comprometido."],["Lote econômico de produção","Lote ótimo quando o item entra no estoque aos poucos durante a produção."],["Índice sazonal","Demanda do período dividida pelo nível médio (média móvel centrada)."],["Dessazonalizar","Dividir a demanda pelo índice sazonal para enxergar nível e tendência."],["Regressão múltipla","Modelo em que a demanda depende de duas ou mais variáveis (ex.: preço próprio e do concorrente)."],["Erro-padrão da estimativa","Dispersão dos dados em torno da reta de regressão; base do intervalo da previsão."],["RCCP","Planejamento grosseiro de capacidade: verifica se o MPS cabe nos recursos críticos."],["Lote fixo","Produz ou compra sempre múltiplos de uma quantidade definida."],["Lote mínimo","Produz a necessidade, mas nunca menos que um mínimo."],["Liberação de ordem planejada","Recebimento planejado recuado do lead time no registro do MRP."],["Item fantasma","Submontagem transitória, que não vai para estoque."],["Makespan","Tempo até o término da última ordem programada."],["Regra SPT","Sequencia primeiro as ordens com menor tempo de processamento."],["Regra EDD","Sequencia primeiro as ordens com data de entrega mais próxima."],["Regra de Johnson","Sequenciamento ótimo (makespan mínimo) para 2 máquinas em série."],["Razão crítica","Tempo até a entrega dividido pelo tempo de processamento restante."],["Fill rate","Proporção das unidades demandadas que foram atendidas."],["OTIF","Pedidos entregues no prazo e completos."],["Giro de estoque","Consumo no período dividido pelo estoque médio."]],"intro":"A primeira parte do PCP, da previsão ao pedido de material: **prever a demanda** (médias móveis, amortecimento exponencial simples e com tendência, parametrização com o **Solver**), usar **regressão** e **índices sazonais**, fazer o **planejamento agregado** (S&OP), montar o **plano mestre (PMP)** com regras de lote e **custos otimizados**, montar a **estrutura de produto**, calcular o **registro do MRP** com capacidade, **sequenciar** ordens (SPT, EDD, Johnson) e dimensionar **estoques** (ponto de pedido, descontos e indicadores). O Módulo 3 do curso aprofunda cada tópico em 3 níveis, com muitos exercícios.","formulas":[[["Fₜ₊₁ = Fₜ + α·(Aₜ − Fₜ)","suavização exponencial"],["MAD = Σ|eₜ| ÷ n","desvio absoluto médio"],["TS = Σeₜ ÷ MAD","sinal de rastreamento"]],[["Produção nivelada = demanda total ÷ nº de períodos","estratégia level"],["Eₜ = Eₜ₋₁ + Pₜ − Dₜ","estoque ao fim do período"]],[["Eₜ = Eₜ₋₁ + PMPₜ − máx(Prevₜ, Pedₜ)","estoque projetado"],["ATP = PMP (+ estoque inicial no 1º período) − pedidos até o próximo PMP","disponível para promessa"]],[["NB = quantidade do pai × quantidade por unidade","necessidade bruta"],["NL = máx(0; NB − estoque − RP + ES)","necessidade líquida"]],[["Fₜ₊₁ = (Dₜ + Dₜ₋₁ + … + Dₜ₋ₙ₊₁) ÷ n","média móvel simples"],["Fₜ₊₁ = a₀Dₜ + a₁Dₜ₋₁ + … ;  Σaᵢ = 1","média móvel ponderada"],["Fₜ₊₁ = α·Dₜ + (1 − α)·Fₜ","amortecimento exponencial simples"],["Sₜ = α·Dₜ + (1 − α)·Fₜ ;  Tₜ = β·(Sₜ − Sₜ₋₁) + (1 − β)·Tₜ₋₁","nível e tendência (Holt)"],["Fₜ₊ₖ = Sₜ + k·Tₜ","previsão com tendência"],["DAM = Σ|Fᵢ − Dᵢ| ÷ k ;  EQM = Σ(Fᵢ − Dᵢ)² ÷ k","medidas de erro"]],[["NBcomp = liberação planejada do pai × quantidade por unidade","explosão da estrutura"],["NL = máx(0; NB − estoque − RP)","necessidade líquida"],["Data de liberação = data de necessidade − lead time","defasagem"]],[["Q* = √(2DS ÷ H)","lote econômico de compra"],["Qp = √[2DS ÷ (H · (1 − d/p))]","lote econômico de produção (d = taxa de consumo; p = taxa de produção)"],["CT = D·c + (D/Q)·S + (Q/2)·H","custo total com o preço do item (descontos)"],["M = d̄·(P + LT) + ES ;  Pedido = M − posição","revisão periódica"]],[["Utilização = horas usadas ÷ horas disponíveis","uso da capacidade"],["Confiabilidade de entrega = pedidos no prazo ÷ total de pedidos","indicador típico do PCP"]],[["b = (nΣxy − ΣxΣy) ÷ (nΣx² − (Σx)²) ;  a = ȳ − b·x̄","reta de mínimos quadrados"],["c = (XᵀX)⁻¹·Xᵀ·d","coeficientes em forma matricial"],["s_yx = √[Σ(y − ŷ)² ÷ (n − 2)]","erro-padrão da estimativa"],["ŷ ± t·s_yx","intervalo aproximado da previsão"]],[["IS = D ÷ MMC","índice sazonal do período"],["ISM = média dos IS do mesmo trimestre","índice sazonal médio"],["D dessaz. = D ÷ ISM","dessazonalizar"],["F = F dessaz. × ISM","sazonalizar a previsão"]],[["Trabalhadores = D × HH por unidade ÷ horas por trabalhador","estratégia de acompanhar"],["Eₜ = Eₜ₋₁ + Pₜ − Dₜ","balanço de estoque"],["Custo total = Σ(contratação + demissão + HE + estoque + falta)","comparação de estratégias"]],[["Necessidade = D + Emín − E inicial","o que falta na semana"],["Lote fixo: P = ⌈necessidade ÷ L⌉ × L","menor múltiplo do lote"],["Lote mínimo: P = máx(necessidade; Lmín)","nunca abaixo do mínimo"],["CT = cs·(semanas com produção) + cl·(lotes) + cm·Σ(Eᵢ + E_f)/2","custo do MPS"]],[["NL = máx(0; NB + ES − RP − Disp(t−1))","necessidade líquida com estoque de segurança"],["Disp(t) = Disp(t−1) + RP + Receb. planejado − NB","estoque projetado"],["Liberação(t − LT) = Recebimento planejado(t)","defasagem do lead time"],["HH(t) = Σ liberaçõesᵢ(t) × hᵢ","carga para comparar com a capacidade"]],[["Qtd total do item = Π (quantidades por unidade ao longo do caminho)","quantidade acumulada na árvore"],["NB(item comum) = Σ NB vindas de cada pai","soma antes do cálculo"]],[["Fluxo médio = Σ Cᵢ ÷ n","Cᵢ = término da ordem i"],["Atraso Tᵢ = máx(0; Cᵢ − dᵢ)","dᵢ = data de entrega"],["Folga = dᵢ − agora − tempo restante","regra da menor folga"],["RC = (dᵢ − agora) ÷ tempo restante","razão crítica (< 1: atrasada)"]],[["PP = d̄·LT + ES","ponto de pedido"],["ES = z·σ_d·√LT","demanda Normal e lead time fixo"],["CT = D·c + (D/Q)·S + (Q/2)·i·c","custo total com desconto"],["Giro = consumo anual ÷ estoque médio ;  Cobertura = estoque ÷ consumo diário","indicadores"]]]},"g-gempr":{"glossario":[["Empreendedorismo","Identificar e explorar oportunidades criando valor."],["Intraempreendedorismo","Empreender dentro de uma organização existente."],["Lean startup","Abordagem de validar hipóteses de negócio rapidamente."],["MVP","Produto mínimo viável para testar hipóteses."],["Pivotar","Mudar a estratégia com base no aprendizado."],["Business Model Canvas","Quadro de 9 blocos que descreve o modelo de negócio."],["Proposta de valor","Benefício que o negócio oferece ao cliente."],["Capital de giro","Recursos para financiar a operação do dia a dia."],["MEI","Microempreendedor individual."],["Simples Nacional","Regime tributário simplificado para micro e pequenas empresas."]],"intro":"Empreender é identificar oportunidades e transformá-las em negócios — dentro de uma empresa (intraempreendedorismo) ou abrindo a sua. A disciplina trata de **oportunidade e validação**, **modelo de negócio (Canvas)**, **plano de negócios e viabilidade** e **formalização** no Brasil.","formulas":[[],[["Taxa de conversão = clientes que compraram ÷ clientes abordados","métrica de validação"]],[],[["PE = custos fixos ÷ margem de contribuição unitária","ponto de equilíbrio"],["Capital de giro ≈ custos do ciclo operacional (estoques + prazo a receber − prazo a pagar)","necessidade de caixa para operar"]]]},"g-projprod":{"glossario":[["PDP","Processo de desenvolvimento de produto."],["Stage-gate","Desenvolvimento em etapas com portões de decisão."],["Engenharia simultânea","Trabalho integrado das áreas desde o início do projeto."],["QFD","Desdobramento da função qualidade."],["Casa da qualidade","Matriz do QFD que relaciona requisitos do cliente e características técnicas."],["Modelo de Kano","Classificação dos requisitos: obrigatórios, desempenho, encantamento."],["DFM","Projeto para manufatura."],["DFA","Projeto para montagem."],["DFMEA","FMEA de projeto."],["Ciclo de vida do produto","Introdução, crescimento, maturidade e declínio."],["Patente","Direito de exclusividade sobre uma invenção por prazo determinado."],["Inovação","Implementação de produto, processo ou método novo ou significativamente melhorado que gera valor (Manual de Oslo). Invenção não é inovação."],["Matriz BCG","Classifica produtos por crescimento do mercado e participação: estrela, interrogação, vaca leiteira e abacaxi."],["ECV","Valor comercial esperado de um projeto: considera probabilidades de sucesso técnico e comercial e os custos."],["PNID","Filtro de ideias: positivo, negativo, interessante e duvidoso."],["Business Model Canvas","Quadro de 9 blocos que descreve o modelo de negócio."],["Busca de anterioridade","Pesquisa do estado da técnica (patentes e publicações) antes de desenvolver ou patentear."],["IPC","Classificação Internacional de Patentes, seções A a H."],["Desenho industrial","Proteção da forma ornamental de um objeto; até 25 anos no Brasil."],["Modelo de utilidade","Patente para melhoria funcional em objeto de uso prático; 15 anos no Brasil."],["Árvore da qualidade demandada","Organização em níveis das qualidades que o cliente deseja, obtidas em questionário aberto."],["Síntese funcional","Desdobramento da função global em subfunções com fluxos de energia, material e sinal."],["Matriz morfológica","Combina princípios de solução para cada subfunção e gera concepções."],["Matriz de Pugh","Compara alternativas com uma referência usando +, 0 e −."],["Arquitetura modular","Produto dividido em módulos com funções e interfaces padronizadas."],["Verificação","Conferir se o produto atende às especificações."],["Validação","Conferir se o produto atende ao uso real do cliente."],["ECO","Ordem de mudança de engenharia, emitida após análise de impacto."],["Custo-alvo","Preço-alvo menos a margem desejada."],["Índice de valor","Importância relativa da função dividida pela sua participação no custo."],["Eficiência de montagem","3 s × peças mínimas ÷ tempo total de montagem (Boothroyd)."],["ACV","Avaliação do ciclo de vida (ISO 14040/14044)."],["MTBF","Tempo médio entre falhas; 1 ÷ λ com taxa de falha constante."]],"intro":"Do problema do cliente ao produto na linha: o **processo de desenvolvimento de produto (PDP)**, inovação e portfólio (**matriz BCG**, **ECV**), planejamento estratégico do produto (**Canvas, SWOT, PNID**), o **projeto informacional** (questionários e **modelo de Kano**), a tradução da voz do cliente (**QFD**), o projeto para **fabricação e montagem (DFM/DFA)**, a análise de riscos (**FMEA**), o **projeto conceitual** (síntese funcional, matriz morfológica e seleção), o **projeto detalhado** com protótipos, verificação e validação, **custo-alvo e análise de valor**, **ecodesign e confiabilidade**, o **ciclo de vida** e a **propriedade intelectual** com busca de anterioridade de patentes.","formulas":[[],[["Importância técnica = Σ (peso do cliente × relação)","priorização das características (ex.: relações 9, 3, 1)"]],[["NPR = S × O × D","priorização no FMEA"],["Eficiência de montagem (Boothroyd) ≈ 3 s × nº mínimo teórico de peças ÷ tempo total de montagem","índice de DFA"]],[],[["ECV = [(VP × Pcs) − C] × Pts − D","valor comercial esperado: VP = valor presente dos ganhos futuros; Pcs = probabilidade de sucesso comercial; C = custo de lançamento; Pts = probabilidade de sucesso técnico; D = custo de desenvolvimento"],["ROI = (ganho − investimento) ÷ investimento","retorno sobre o investimento"]],[],[],[["Importância relativa do requisito = nota média do requisito ÷ Σ notas médias","peso usado no QFD"]],[["Nº de concepções = Π (opções de cada subfunção)","matriz morfológica"],["Nota = Σ (peso do critério × nota)","matriz de decisão ponderada"]],[["Custo de mudança ≈ ×10 a cada fase avançada","regra prática (\"regra de 10\")"]],[["Custo-alvo = preço-alvo × (1 − margem)","margem sobre o preço"],["Índice de valor = % importância ÷ % custo","análise de valor"],["E = 3·Nmín ÷ tempo total (s)","eficiência de montagem de Boothroyd"]],[["R(t) = e^(−λt) ;  MTBF = 1 ÷ λ","confiabilidade com taxa de falha constante"],["Série: R = Π Rᵢ","todos precisam funcionar"],["Paralelo: R = 1 − Π (1 − Rᵢ)","redundância"]]]},"g-gproj":{"glossario":[["Projeto","Esforço temporário para criar um resultado único."],["TAP","Termo de abertura do projeto."],["EAP","Estrutura analítica do projeto."],["Caminho crítico","Sequência de atividades com folga zero que define a duração."],["Folga total","Quanto uma atividade pode atrasar sem atrasar o projeto."],["PERT","Técnica de estimativa com três durações."],["EVM","Gerenciamento do valor agregado."],["CPI","Índice de desempenho de custo."],["SPI","Índice de desempenho de prazo."],["Scrum","Framework ágil com sprints e papéis definidos."],["Portfólio","Conjunto de projetos e programas selecionados e priorizados segundo a estratégia."],["Programa","Grupo de projetos relacionados gerenciados em conjunto."],["PMBOK","Guia de conhecimentos em gerenciamento de projetos publicado pelo PMI."],["Grupos de processos","Iniciação, planejamento, execução, monitoramento e controle, encerramento (PMBOK 6ª ed.)."],["Domínios de desempenho","Oito áreas de foco do PMBOK 7ª ed. para entregar resultados."],["Requisito não funcional","Descreve como o produto deve funcionar (desempenho, segurança, usabilidade)."],["Matriz de rastreabilidade","Liga cada requisito à origem, à entrega e ao teste."],["MoSCoW","Priorização: must, should, could e won't have."],["Pacote de trabalho","Nível mais baixo da EAP, com responsável, custo e duração."],["Dicionário da EAP","Descrição detalhada de cada pacote de trabalho."],["Matriz RACI","Responsável, aprovador, consultado e informado por tarefa."],["Folga livre","Atraso possível sem atrasar nenhuma sucessora."],["Fast tracking","Executar em paralelo atividades normalmente sequenciais."],["Crashing","Adicionar recursos a atividades críticas para reduzir o prazo."],["Curva S","Custo acumulado planejado ao longo do tempo."],["ENT (EAC)","Estimativa do custo total no término do projeto."],["IDCP (TCPI)","Eficiência de custo necessária no restante do projeto para cumprir o orçamento."],["Reserva de contingência","Recursos para riscos identificados; faz parte da linha de base."],["Reserva gerencial","Recursos para imprevistos; fica fora da linha de base."],["VME","Valor monetário esperado: probabilidade × impacto."],["Registro de riscos","Lista dos riscos com probabilidade, impacto, dono, resposta e gatilho."],["Matriz poder × interesse","Classifica partes interessadas para definir a estratégia de engajamento."],["Canais de comunicação","n(n − 1)/2 para n pessoas."],["Contrato de preço fixo","O fornecedor assume o risco de custo; exige escopo claro."],["Lições aprendidas","Registro do que funcionou e do que mudar nos próximos projetos."],["Velocidade","Pontos de história entregues por sprint."],["Limite de WIP","Máximo de itens em andamento numa coluna do quadro Kanban."]],"intro":"Projetos entregam mudanças: nova linha, implantação de ERP, lançamento de produto. A disciplina cobre o **PMBOK** (grupos de processos, princípios e domínios), **requisitos e escopo** (rastreabilidade), **EAP, dicionário e matriz RACI**, **cronograma** (Gantt, estimativas, caminho crítico e **PERT probabilístico**), **custos e valor agregado** (com previsões ENT e IDCP), **riscos** (VME e respostas), **partes interessadas e comunicação**, **qualidade, aquisições e encerramento** e **métodos ágeis** na prática. O Módulo 2 do curso aprofunda em 3 níveis.","formulas":[[],[["tₑ = (a + 4m + b) ÷ 6","duração esperada (PERT)"],["σ = (b − a) ÷ 6","desvio-padrão da atividade"],["Folga = LS − ES","folga total"]],[["CPI = EV ÷ AC","desempenho de custo"],["SPI = EV ÷ PV","desempenho de prazo"],["EAC = BAC ÷ CPI","estimativa no término"]],[["VME do risco = probabilidade × impacto","priorização e reserva de contingência"]],[],[],[["Custo do projeto = Σ custos dos pacotes de trabalho (+ reservas)","estimativa bottom-up a partir da EAP"]],[["EF = ES + d ;  LS = LF − d","datas mais cedo e mais tarde"],["Folga total = LS − ES ;  Folga livre = mín(ES das sucessoras) − EF","folgas"],["σ do caminho = √(Σ σᵢ²)","desvio-padrão do caminho crítico"],["Z = (T − Tₑ) ÷ σ do caminho","probabilidade de terminar até T (tabela normal)"]],[["IDC = VA ÷ CR ;  IDP = VA ÷ VP","índices de custo e de prazo"],["ENT = ONT ÷ IDC","estimativa no término (desempenho continua)"],["EPT = ENT − CR ;  VNT = ONT − ENT","para terminar e variação no término"],["IDCP = (ONT − VA) ÷ (ONT − CR)","eficiência necessária para cumprir o orçamento"]],[["VME = P × I","valor monetário esperado"],["Reserva ≈ Σ VME(ameaças) − Σ VME(oportunidades)","base da reserva de contingência"],["Prioridade = P × I (escala 1–5)","matriz de probabilidade e impacto"]],[["Canais = n·(n − 1) ÷ 2","canais de comunicação"]],[["Fazer: CF + cv·Q ;  comprar: p·Q → ponto de equilíbrio Q = CF ÷ (p − cv)","fazer ou comprar"],["Nota do fornecedor = Σ (peso × nota)","seleção ponderada"]],[["Sprints ≈ pontos do backlog ÷ velocidade","previsão de entrega"],["Lead time ≈ WIP ÷ throughput","lei de Little no quadro Kanban"]]]},"g-pcp2":{"glossario":[["RCCP","Verificação grosseira de capacidade do PMP."],["CRP","Verificação detalhada de capacidade das ordens do MRP."],["Carga","Horas necessárias para cumprir o plano."],["MTP (SPT)","Menor tempo de processamento primeiro."],["DD (EDD)","Menor data de entrega primeiro."],["Regra de Johnson","Sequenciamento ótimo para duas máquinas em série."],["Aderência ao programa","Proporção das ordens concluídas conforme o programado."],["OTIF","Entregas no prazo e completas."],["CONWIP","Sistema puxado com WIP total constante."],["Tambor-pulmão-corda","Programação pela Teoria das Restrições."],["APS","Sistema avançado de planejamento e programação."]],"intro":"A segunda parte do PCP vai do plano ao chão de fábrica: **capacidade** (RCCP e CRP), **sequenciamento e programação**, **controle da produção** e os **sistemas de coordenação** (MRP, kanban, CONWIP, tambor-pulmão-corda, APS). Módulos 3 e 6 do curso aprofundam os temas.","formulas":[[["Carga = Σ qᵢ × tpᵢ","horas necessárias"],["Ocupação = carga ÷ capacidade × 100%","acima de 100% = sobrecarga"]],[["Tempo de fluxo = término − liberação","tempo no sistema"],["Atraso = máx(0; término − data de entrega)","tardiness"]],[["Aderência = ordens concluídas no prazo ÷ ordens programadas","cumprimento do programa"],["OTIF = pedidos no prazo e completos ÷ total","nível de serviço"],["Lead time = WIP ÷ taxa","lei de Little"]],[["N = D × L × (1 + α) ÷ C","número de kanbans"]]]},"g-gestr":{"glossario":[["Missão","Razão de existir da organização."],["Visão","Situação futura desejada."],["PESTEL","Análise de fatores políticos, econômicos, sociais, tecnológicos, ecológicos e legais."],["Cinco forças","Modelo de Porter da atratividade do setor."],["Cadeia de valor","Atividades que criam valor na empresa (Porter)."],["VRIO","Valor, raridade, imitabilidade, organização."],["SWOT","Forças, fraquezas, oportunidades e ameaças."],["Estratégias genéricas","Custo, diferenciação e foco."],["Critério ganhador de pedido","Fator que faz o cliente escolher a empresa."],["Critério qualificador","Requisito mínimo para ser considerado pelo cliente."],["BSC","Balanced Scorecard."],["OKR","Objetivos e resultados-chave."]],"intro":"Estratégia é escolher **onde competir e como vencer**. A disciplina cobre missão e visão, **análise externa** (PESTEL, 5 forças de Porter), **análise interna** (cadeia de valor, VRIO), **SWOT**, **estratégias genéricas**, **estratégia de operações** e a execução com **BSC e OKR**.","formulas":[[],[],[],[["Atingimento do KR = (valor atual − inicial) ÷ (meta − inicial)","progresso de um resultado-chave"]]]},"g-logist":{"glossario":[["Cadeia de suprimentos","Rede de empresas do fornecedor ao cliente final."],["Efeito chicote","Amplificação da variação da demanda ao longo da cadeia."],["VMI","Estoque gerenciado pelo fornecedor."],["Curva ABC","Classificação de itens pela importância (valor)."],["Lote econômico","Quantidade que minimiza custos de pedir e manter."],["Ponto de pedido","Nível de estoque que dispara a reposição."],["Estoque de segurança","Proteção contra variações da demanda e do lead time."],["FEFO","Primeiro que vence, primeiro que sai."],["WMS","Sistema de gestão de armazém."],["Picking","Separação de itens para os pedidos."],["Fill rate","Proporção da quantidade pedida que foi atendida."],["Logística reversa","Fluxo de retorno de produtos, embalagens e resíduos."]],"intro":"Logística leva o produto certo, na quantidade certa, ao lugar certo, no tempo certo, com o menor custo total. A disciplina trata da **cadeia de suprimentos**, **gestão de estoques** (ABC, lote econômico, ponto de pedido, estoque de segurança), **armazenagem**, **transporte** e **nível de serviço**.","formulas":[[["Amplificação = variância dos pedidos ÷ variância da demanda","medida do efeito chicote"]],[["Q* = √(2·D·S ÷ H)","lote econômico"],["PP = d̄ · LT + ES","ponto de pedido"],["ES = z · σ_d · √LT","estoque de segurança"]],[["Taxa de ocupação = posições ocupadas ÷ posições totais","uso do armazém"],["Produtividade de picking = linhas separadas ÷ hora","desempenho da separação"]],[["Custo por unidade = custo da viagem ÷ unidades transportadas","efeito da consolidação"],["Fill rate = quantidade atendida ÷ quantidade pedida","nível de serviço"]]]},"g-tcc":{"glossario":[["Problema de pesquisa","Pergunta que o trabalho pretende responder."],["Objetivo geral","O que o trabalho pretende alcançar como um todo."],["Objetivos específicos","Etapas mensuráveis para atingir o objetivo geral."],["Revisão da literatura","Síntese do conhecimento existente sobre o tema."],["Estudo de caso","Investigação aprofundada de um caso no seu contexto."],["Pesquisa-ação","Pesquisa em que o pesquisador participa da intervenção."],["Limitações","Restrições do estudo que afetam as conclusões."],["Banca","Comissão que avalia o trabalho."]],"intro":"O projeto final integra o curso num trabalho autoral: um **problema real de Engenharia de Produção**, resolvido com **método**, **dados** e **ferramentas** das disciplinas, documentado e defendido. Projeto Final I costuma focar no problema, na revisão e no método; o II, na execução, nos resultados e na defesa.","formulas":[[],[],[["Ganho (%) = (antes − depois) ÷ antes × 100","forma comum de apresentar resultados de melhoria"]],[]]},"g-anorg":{"glossario":[["Teoria contingencial","A melhor estrutura depende do ambiente, tecnologia e tamanho."],["Isomorfismo","Tendência de organizações se tornarem semelhantes (teoria institucional)."],["Racionalidade limitada","Decisões com informação e capacidade cognitiva limitadas (Simon)."],["Modelo 7S","Estrutura de diagnóstico da McKinsey com 7 elementos."],["Seis caixas","Modelo de diagnóstico de Weisbord."],["Cultura organizacional","Pressupostos e valores compartilhados."],["Poder","Capacidade de influenciar comportamentos e decisões."],["Modelo de Lewin","Descongelar, mudar e recongelar."],["Aprendizagem de circuito duplo","Aprendizagem que questiona as premissas (Argyris)."],["Organização que aprende","Organização que desenvolve continuamente a capacidade de aprender (Senge)."]],"intro":"Como diagnosticar uma organização e conduzir mudanças: **modelos de diagnóstico**, **teorias organizacionais**, **cultura e poder**, **mudança organizacional** e **aprendizagem**. É a disciplina que fecha a visão de gestão do engenheiro de produção, útil para liderar transformações (Lean, ERP, reestruturações).","formulas":[[],[],[],[]]}}};
